pub(crate) fn builtin_cos(args: &[Value], span: &Span) -> Result<Value, Galat> {
    match args[0] {
        Value::Number(n) => Ok(Value::Number(n.cos())),
        _ => Err(Galat::runtime("Fungsi 'cos' memerlukan argumen angka (radian)", span)),
    }
}

