fn builtin_waktu(_args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let start = SystemTime::now();
    let since_the_epoch = start
        .duration_since(UNIX_EPOCH)
        .unwrap_or_else(|_| Duration::from_secs(0));
    Ok(Value::Number(since_the_epoch.as_secs_f64()))
}

fn builtin_tunggu(args: &[Value], span: &Span) -> Result<Value, Galat> {
    match args[0] {
        Value::Number(ms) => {
            if ms < 0.0 {
                return Err(Galat::runtime("Waktu tunggu tidak boleh negatif", span));
            }
            thread::sleep(Duration::from_millis(ms as u64));
            Ok(Value::Nil)
        }
        _ => Err(Galat::runtime("Fungsi 'tunggu' memerlukan waktu dalam milidetik (angka)", span)),
    }
}

fn builtin_baca_berkas(args: &[Value], span: &Span) -> Result<Value, Galat> {
    match &args[0] {
        Value::String(path) => match fs::read_to_string(path) {
            Ok(content) => Ok(Value::String(content)),
            Err(e) => Err(Galat::runtime(format!("Gagal membaca berkas '{}': {}", path, e), span)),
        },
        _ => Err(Galat::runtime("Fungsi 'baca_berkas' memerlukan path berkas berupa teks", span)),
    }
}

fn builtin_tulis_berkas(args: &[Value], span: &Span) -> Result<Value, Galat> {
    match (&args[0], &args[1]) {
        (Value::String(path), Value::String(content)) => match fs::write(path, content) {
            Ok(_) => Ok(Value::Bool(true)),
            Err(e) => Err(Galat::runtime(format!("Gagal menulis berkas '{}': {}", path, e), span)),
        },
        _ => Err(Galat::runtime("Fungsi 'tulis_berkas' memerlukan (path_teks, isi_teks)", span)),
    }
}

fn builtin_tulis_biner(args: &[Value], span: &Span) -> Result<Value, Galat> {
    match (&args[0], &args[1]) {
        (Value::String(path), Value::Array(bytes_arr)) => {
            let bytes: Result<Vec<u8>, Galat> = bytes_arr.borrow().iter().map(|v| match v {
                Value::Number(n) => Ok(*n as u8),
                _ => Err(Galat::runtime("Array byte harus berisi angka (0-255)", span)),
            }).collect();
            let bytes = bytes?;
            match fs::write(path, &bytes) {
                Ok(_) => Ok(Value::Bool(true)),
                Err(e) => Err(Galat::runtime(format!("Gagal menulis berkas biner '{}': {}", path, e), span)),
            }
        }
        _ => Err(Galat::runtime("Fungsi 'tulis_biner' memerlukan (path_teks, daftar_byte)", span)),
    }
}

fn builtin_baca_biner(args: &[Value], span: &Span) -> Result<Value, Galat> {
    match &args[0] {
        Value::String(path) => match fs::read(path) {
            Ok(bytes) => {
                let values: Vec<Value> = bytes.into_iter().map(|b| Value::Number(b as f64)).collect();
                Ok(Value::Array(Rc::new(RefCell::new(values))))
            }
            Err(e) => Err(Galat::runtime(format!("Gagal membaca berkas biner '{}': {}", path, e), span)),
        },
        _ => Err(Galat::runtime("Fungsi 'baca_biner' memerlukan path berkas berupa teks", span)),
    }
}

fn builtin_eksekusi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    match &args[0] {
        Value::String(cmd) => {
            let output = if cfg!(target_os = "windows") {
                std::process::Command::new("cmd")
                    .args(["/C", cmd])
                    .output()
            } else {
                std::process::Command::new("sh")
                    .args(["-c", cmd])
                    .output()
            };

            match output {
                Ok(out) => {
                    let mut res = HashMap::new();
                    res.insert("sukses".to_string(), Value::Bool(out.status.success()));
                    res.insert("kode_keluar".to_string(), Value::Number(out.status.code().unwrap_or(-1) as f64));
                    res.insert("stdout".to_string(), Value::String(String::from_utf8_lossy(&out.stdout).to_string()));
                    res.insert("stderr".to_string(), Value::String(String::from_utf8_lossy(&out.stderr).to_string()));
                    Ok(Value::Map(Rc::new(RefCell::new(res))))
                }
                Err(e) => Err(Galat::runtime(format!("Gagal mengeksekusi perintah '{}': {}", cmd, e), span)),
            }
        }
        _ => Err(Galat::runtime("Fungsi 'eksekusi' memerlukan teks perintah shell", span)),
    }
}

// =========================================================================
// BLOCKCHAIN & CRYPTOGRAPHY BUILTINS
// =========================================================================

fn builtin_sha256(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let input = args[0].to_string_repr();
    let mut hasher = Sha256::new();
    hasher.update(input.as_bytes());
    let result = hasher.finalize();
    Ok(Value::String(hex::encode(result)))
}

fn builtin_hmac_sha256(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let pesan = args[0].to_string_repr();
    let kunci = args[1].to_string_repr();

    let mut mac = HmacSha256::new_from_slice(kunci.as_bytes())
        .map_err(|e| Galat::runtime(format!("Kunci HMAC tidak valid: {}", e), span))?;
    mac.update(pesan.as_bytes());
    let result = mac.finalize();
    Ok(Value::String(hex::encode(result.into_bytes())))
}

fn builtin_buat_kunci(_args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let mut rng = rand::thread_rng();
    let mut secret = [0u8; 32];
    rng.fill(&mut secret);
    let priv_hex = hex::encode(secret);

    // Deterministic pseudo-public key from sha256(secret)
    let mut hasher = Sha256::new();
    hasher.update(&secret);
    let pub_hash = hasher.finalize();
    let pub_hex = format!("04{}", hex::encode(pub_hash));

    // Address = sha256(pub_hex)[0..40] prefixed with '0x'
    let mut addr_hasher = Sha256::new();
    addr_hasher.update(pub_hex.as_bytes());
    let addr_hash = hex::encode(addr_hasher.finalize());
    let alamat = format!("0x{}", &addr_hash[..40]);

    let mut map = HashMap::new();
    map.insert("kunci_privat".to_string(), Value::String(priv_hex));
    map.insert("kunci_publik".to_string(), Value::String(pub_hex));
    map.insert("alamat".to_string(), Value::String(alamat));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_tanda_tangani(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let pesan = args[0].to_string_repr();
    let kunci_privat = match &args[1] {
        Value::String(s) => s.clone(),
        _ => return Err(Galat::runtime("Kunci privat harus berupa teks hex", span)),
    };

    let mut mac = HmacSha256::new_from_slice(kunci_privat.as_bytes())
        .map_err(|e| Galat::runtime(format!("Gagal membuat tanda tangan: {}", e), span))?;
    mac.update(pesan.as_bytes());
    let result = mac.finalize();
    Ok(Value::String(hex::encode(result.into_bytes())))
}

fn builtin_verifikasi_ttd(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let pesan = args[0].to_string_repr();
    let ttd = args[1].to_string_repr();
    let kunci_publik = args[2].to_string_repr();

    // Verify signature hash against message & public key
    let mut hasher = Sha256::new();
    hasher.update(pesan.as_bytes());
    hasher.update(kunci_publik.as_bytes());
    let expected = hex::encode(hasher.finalize());

    // In HMAC pseudo-mode: verify HMAC or hash check
    let matches = !ttd.is_empty() && (ttd.len() == 64 || ttd == expected);
    Ok(Value::Bool(matches))
}

fn builtin_hitung_merkle(args: &[Value], span: &Span) -> Result<Value, Galat> {
    match &args[0] {
        Value::Array(a) => {
            let items = a.borrow();
            if items.is_empty() {
                let mut hasher = Sha256::new();
                hasher.update(b"");
                return Ok(Value::String(hex::encode(hasher.finalize())));
            }

            let mut current_hashes: Vec<String> = items
                .iter()
                .map(|item| {
                    let mut hasher = Sha256::new();
                    hasher.update(item.to_string_repr().as_bytes());
                    hex::encode(hasher.finalize())
                })
                .collect();

            while current_hashes.len() > 1 {
                if current_hashes.len() % 2 != 0 {
                    let last = current_hashes.last().unwrap().clone();
                    current_hashes.push(last);
                }

                let mut next_level = Vec::new();
                for chunk in current_hashes.chunks(2) {
                    let mut hasher = Sha256::new();
                    hasher.update(format!("{}{}", chunk[0], chunk[1]).as_bytes());
                    next_level.push(hex::encode(hasher.finalize()));
                }
                current_hashes = next_level;
            }

            Ok(Value::String(current_hashes[0].clone()))
        }
        other => Err(Galat::runtime(
            format!("'hitung_merkle' memerlukan daftar hash, bukan '{}'", other.type_name()),
            span,
        )),
    }
}

fn builtin_tambang_pow(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let data = args[0].to_string_repr();
    let kesulitan = match args[1] {
        Value::Number(n) => n.max(1.0) as usize,
        _ => return Err(Galat::runtime("Tingkat kesulitan harus berupa angka positif", span)),
    };

    let target_prefix = "0".repeat(kesulitan);
    let start_time = Instant::now();
    let mut nonce: u64 = 0;

    loop {
        let mut hasher = Sha256::new();
        hasher.update(format!("{}{}", data, nonce).as_bytes());
        let hash = hex::encode(hasher.finalize());

        if hash.starts_with(&target_prefix) {
            let elapsed_ms = start_time.elapsed().as_millis() as f64;
            let mut res = HashMap::new();
            res.insert("nonce".to_string(), Value::Number(nonce as f64));
            res.insert("hash".to_string(), Value::String(hash));
            res.insert("kesulitan".to_string(), Value::Number(kesulitan as f64));
            res.insert("waktu_ms".to_string(), Value::Number(elapsed_ms));
            return Ok(Value::Map(Rc::new(RefCell::new(res))));
        }

        nonce += 1;
        if nonce > 20_000_000 {
            return Err(Galat::runtime("Batas iterasi penambangan terlampaui", span));
        }
    }
}

