fn builtin_game_render_html(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let judul = match &args[0] {
        Value::Map(m) => m.borrow().get("judul").map(|v| v.to_string_repr()).unwrap_or_else(|| "Widya Game".to_string()),
        _ => "Widya Game 2D".to_string(),
    };

    let html = format!(
        r#"<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <title>{}</title>
    <style>
        body {{ margin: 0; background: #0f172a; display: flex; justify-content: center; align-items: center; height: 100vh; font-family: sans-serif; color: white; }}
        canvas {{ background: #1e293b; border: 3px solid #6366f1; border-radius: 12px; box-shadow: 0 10px 30px rgba(0,0,0,0.5); }}
    </style>
</head>
<body>
    <div style="text-align: center;">
        <h2>🎮 {}</h2>
        <canvas id="gameCanvas" width="800" height="500"></canvas>
        <p style="color: #94a3b8; font-size: 13px;">Gunakan tombol Panah / Tombol Keyboard untuk menggerakkan karakter</p>
    </div>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        let player = {{ x: 100, y: 220, vx: 0, vy: 0, size: 30, color: '#38bdf8' }};
        let gems = [{{ x: 400, y: 150 }}, {{ x: 600, y: 300 }}, {{ x: 250, y: 380 }}];
        let score = 0;

        window.addEventListener('keydown', e => {{
            if (e.key === 'ArrowRight' || e.key === 'd') player.vx = 4;
            if (e.key === 'ArrowLeft' || e.key === 'a') player.vx = -4;
            if (e.key === 'ArrowUp' || e.key === 'w') player.vy = -4;
            if (e.key === 'ArrowDown' || e.key === 's') player.vy = 4;
        }});

        window.addEventListener('keyup', e => {{
            if (['ArrowRight', 'ArrowLeft', 'a', 'd'].includes(e.key)) player.vx = 0;
            if (['ArrowUp', 'ArrowDown', 'w', 's'].includes(e.key)) player.vy = 0;
        }});

        function update() {{
            player.x += player.vx;
            player.y += player.vy;

            // Boundaries
            player.x = Math.max(0, Math.min(canvas.width - player.size, player.x));
            player.y = Math.max(0, Math.min(canvas.height - player.size, player.y));

            // Gem Collision
            gems = gems.filter(g => {{
                let dist = Math.hypot((player.x + 15) - g.x, (player.y + 15) - g.y);
                if (dist < 25) {{ score += 10; return false; }}
                return true;
            }});
        }}

        function draw() {{
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Draw Gems
            ctx.fillStyle = '#f59e0b';
            gems.forEach(g => {{
                ctx.beginPath();
                ctx.arc(g.x, g.y, 10, 0, Math.PI * 2);
                ctx.fill();
            }});

            // Draw Player
            ctx.fillStyle = player.color;
            ctx.fillRect(player.x, player.y, player.size, player.size);

            // Draw Score
            ctx.fillStyle = '#ffffff';
            ctx.font = 'bold 16px sans-serif';
            ctx.fillText('Skor: ' + score + ' WIDYA', 20, 30);
        }}

        function loop() {{
            update();
            draw();
            requestAnimationFrame(loop);
        }}
        loop();
    </script>
</body>
</html>"#,
        judul, judul
    );
    Ok(Value::String(html))
}

// --- Bare-Metal Volatile Memory Emulation Buffer ---

fn get_mem_pool() -> &'static std::sync::Mutex<HashMap<usize, f64>> {
    static MEM_POOL: std::sync::OnceLock<std::sync::Mutex<HashMap<usize, f64>>> = std::sync::OnceLock::new();
    MEM_POOL.get_or_init(|| std::sync::Mutex::new(HashMap::new()))
}

pub fn baca_memori_volatil(alamat: usize, _span: &Span) -> Result<Value, Galat> {
    let pool = get_mem_pool().lock().unwrap();
    let val = pool.get(&alamat).copied().unwrap_or(0.0);
    Ok(Value::Number(val))
}

pub fn tulis_memori_volatil(alamat: usize, nilai: &Value, span: &Span) -> Result<Value, Galat> {
    let num = match nilai {
        Value::Number(n) => *n,
        Value::Bool(b) => if *b { 1.0 } else { 0.0 },
        _ => return Err(Galat::runtime("Nilai memori volatil harus berupa angka atau boolean", span)),
    };
    let mut pool = get_mem_pool().lock().unwrap();
    pool.insert(alamat, num);
    Ok(Value::Nil)
}

fn builtin_baca_volatil(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let addr = match args[0] {
        Value::Number(n) => n as usize,
        _ => return Err(Galat::runtime("Alamat memori harus berupa angka", span)),
    };
    baca_memori_volatil(addr, span)
}

fn builtin_tulis_volatil(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let addr = match args[0] {
        Value::Number(n) => n as usize,
        _ => return Err(Galat::runtime("Alamat memori harus berupa angka", span)),
    };
    tulis_memori_volatil(addr, &args[1], span)
}

fn builtin_alokasi_buffer_mentah(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let ukuran = match args[0] {
        Value::Number(n) => n as usize,
        _ => return Err(Galat::runtime("Ukuran buffer harus berupa angka", span)),
    };
    // Return mock pointer address base (e.g., 0x20000000 base RAM)
    let base_addr = 0x20000000 + (ukuran * 4);
    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("PenunjukMentah".to_string()));
    map.insert("alamat".to_string(), Value::Number(base_addr as f64));
    map.insert("ukuran_byte".to_string(), Value::Number(ukuran as f64));
    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

pub(crate) fn builtin_ffi_call_generic(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let args_str: Vec<String> = args.iter().map(|a| a.to_string_repr()).collect();
    println!("[C-FFI Generic Direct Call] Argumen: {}", args_str.join(", "));
    Ok(Value::Number(0.0))
}

