fn builtin_3d_render_html(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let adegan = &args[0];
    let nama_file = if args.len() >= 2 { args[1].to_string_repr() } else { "adegan_3d.html".to_string() };

    let judul = match adegan {
        Value::Map(m) => {
            let map = m.borrow();
            map.get("nama").or_else(|| map.get("judul")).map(|v| v.to_string_repr()).unwrap_or_else(|| "Widya 3D Scene".to_string())
        }
        _ => return Err(Galat::runtime("Diharapkan objek Adegan3D", span)),
    };

    let html = format!(r#"<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>{}</title>
  <style>
    body {{ margin: 0; background: #050505; color: white; overflow: hidden; font-family: sans-serif; }}
    canvas {{ width: 100vw; height: 100vh; display: block; }}
    #hud {{ position: absolute; top: 16px; left: 16px; z-index: 10; background: rgba(15,23,42,0.85); padding: 12px 20px; border-radius: 12px; border: 1px solid #334155; backdrop-filter: blur(8px); }}
  </style>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
</head>
<body>
  <div id="hud">
    <h3 style="margin:0; color:#38bdf8;">🌐 Widya3D WebGL Engine</h3>
    <p style="margin:4px 0 0 0; font-size:12px; color:#94a3b8;">Adegan: <b>{}</b></p>
  </div>
  <script>
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0f172a);
    const camera = new THREE.PerspectiveCamera(60, window.innerWidth/window.innerHeight, 0.1, 1000);
    camera.position.set(0, 5, 15);
    camera.lookAt(0, 0, 0);

    const renderer = new THREE.WebGLRenderer({{ antialias: true }});
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    const light = new THREE.DirectionalLight(0xffffff, 1.2);
    light.position.set(10, 20, 15);
    scene.add(light);
    scene.add(new THREE.AmbientLight(0x404040, 1.5));

    const grid = new THREE.GridHelper(30, 30, 0x6366f1, 0x334155);
    scene.add(grid);

    const geometry = new THREE.BoxGeometry(2, 2, 2);
    const material = new THREE.MeshStandardMaterial({{ color: 0x38bdf8, roughness: 0.3, metalness: 0.8 }});
    const cube = new THREE.Mesh(geometry, material);
    scene.add(cube);

    function animate() {{
      requestAnimationFrame(animate);
      cube.rotation.x += 0.01;
      cube.rotation.y += 0.015;
      renderer.render(scene, camera);
    }}
    animate();

    window.addEventListener('resize', () => {{
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    }});
  </script>
</body>
</html>"#, judul, judul);

    let _ = fs::write(&nama_file, &html);
    Ok(Value::String(html))
}

// --- WidyaCRDT (Conflict-free Replicated Collaborative Sync) ---

fn builtin_crdt_dokumen(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let peer_id = args[0].to_string_repr();
    let doc_name = if args.len() >= 2 { args[1].to_string_repr() } else { "dokumen".to_string() };

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("DokumenCRDT".to_string()));
    map.insert("peer_id".to_string(), Value::String(peer_id.clone()));
    map.insert("client_id".to_string(), Value::String(peer_id));
    map.insert("nama_dokumen".to_string(), Value::String(doc_name));
    map.insert("clock".to_string(), Value::Number(0.0));
    map.insert("daftar_karakter".to_string(), Value::Array(Rc::new(RefCell::new(Vec::new()))));
    map.insert("karakter".to_string(), Value::Array(Rc::new(RefCell::new(Vec::new()))));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_crdt_sisip(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let _pos = match &args[1] { Value::Number(n) => *n as usize, _ => 0 };
    let teks = args[2].to_string_repr();

    match &args[0] {
        Value::Map(m) => {
            let mut map = m.borrow_mut();
            let peer_id = map.get("peer_id").map(|v| v.to_string_repr()).unwrap_or_else(|| "peer".to_string());
            let mut clock = match map.get("clock") { Some(Value::Number(n)) => *n, _ => 0.0 };
            let arr_opt = map.get("daftar_karakter").or_else(|| map.get("karakter")).cloned();

            if let Some(Value::Array(arr)) = arr_opt {
                {
                    let mut items = arr.borrow_mut();
                    for ch in teks.chars() {
                        clock += 1.0;
                        let mut node = HashMap::new();
                        node.insert("ch".to_string(), Value::String(ch.to_string()));
                        node.insert("peer".to_string(), Value::String(peer_id.clone()));
                        node.insert("clock".to_string(), Value::Number(clock));
                        items.push(Value::Map(Rc::new(RefCell::new(node))));
                    }
                }
                map.insert("clock".to_string(), Value::Number(clock));
                Ok(Value::Bool(true))
            } else {
                Err(Galat::runtime("Dokumen CRDT tidak memiliki buffer karakter", span))
            }
        }
        _ => Err(Galat::runtime("Diharapkan objek DokumenCRDT", span)),
    }
}

fn builtin_crdt_gabung(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let target = &args[0];
    let source_nodes: Vec<Value> = match &args[1] {
        Value::Array(arr) => arr.borrow().clone(),
        Value::Map(m) => {
            let map = m.borrow();
            if let Some(Value::Array(a)) = map.get("daftar_karakter").or_else(|| map.get("karakter")) {
                a.borrow().clone()
            } else {
                Vec::new()
            }
        }
        _ => return Err(Galat::runtime("Sumber gabung CRDT harus berupa DokumenCRDT atau daftar karakter", span)),
    };

    match target {
        Value::Map(m_local) => {
            let local_map = m_local.borrow();
            if let Some(Value::Array(local_arr)) = local_map.get("daftar_karakter").or_else(|| local_map.get("karakter")) {
                let mut local_items = local_arr.borrow_mut();
                for node in source_nodes {
                    // Check if node already exists by peer and clock
                    let exists = local_items.iter().any(|existing| {
                        if let (Value::Map(m1), Value::Map(m2)) = (existing, &node) {
                            let map1 = m1.borrow();
                            let map2 = m2.borrow();
                            map1.get("peer") == map2.get("peer") && map1.get("clock") == map2.get("clock")
                        } else {
                            existing == &node
                        }
                    });
                    if !exists {
                        local_items.push(node);
                    }
                }

                // Deterministic LWW / Peer-order sort for total consistency
                local_items.sort_by(|a, b| {
                    if let (Value::Map(m1), Value::Map(m2)) = (a, b) {
                        let map1 = m1.borrow();
                        let map2 = m2.borrow();
                        let peer1 = map1.get("peer").map(|v| v.to_string_repr()).unwrap_or_default();
                        let peer2 = map2.get("peer").map(|v| v.to_string_repr()).unwrap_or_default();
                        let clock1 = match map1.get("clock") { Some(Value::Number(n)) => *n as i64, _ => 0 };
                        let clock2 = match map2.get("clock") { Some(Value::Number(n)) => *n as i64, _ => 0 };

                        peer1.cmp(&peer2).then(clock1.cmp(&clock2))
                    } else {
                        a.to_string_repr().cmp(&b.to_string_repr())
                    }
                });

                Ok(Value::Bool(true))
            } else {
                Err(Galat::runtime("Buffer karakter lokal CRDT tidak valid", span))
            }
        }
        _ => Err(Galat::runtime("Target gabung harus berupa objek DokumenCRDT", span)),
    }
}

fn builtin_crdt_baca(args: &[Value], span: &Span) -> Result<Value, Galat> {
    match &args[0] {
        Value::Map(m) => {
            let map = m.borrow();
            if let Some(Value::Array(arr)) = map.get("daftar_karakter").or_else(|| map.get("karakter")) {
                let items = arr.borrow();
                let mut text = String::new();
                for it in items.iter() {
                    if let Value::Map(m_node) = it {
                        let node_map = m_node.borrow();
                        if let Some(ch_val) = node_map.get("ch") {
                            text.push_str(&ch_val.to_string_repr());
                        }
                    } else if let Value::String(s) = it {
                        text.push_str(s);
                    } else {
                        text.push_str(&it.to_string_repr());
                    }
                }
                Ok(Value::String(text))
            } else {
                Err(Galat::runtime("Dokumen CRDT tidak valid", span))
            }
        }
        _ => Err(Galat::runtime("Diharapkan objek DokumenCRDT", span)),
    }
}

// =========================================================================
// WidyaFHE: Fully Homomorphic Encryption & Encrypted Compute Engine
// =========================================================================

fn builtin_fhe_konteks(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let skema = if !args.is_empty() { args[0].to_string_repr() } else { "CKKS_BFV".to_string() };
    let poly_degree = if args.len() >= 2 {
        match args[1] { Value::Number(n) => n as usize, _ => 8192 }
    } else {
        8192
    };

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("KonteksFHE".to_string()));
    map.insert("skema".to_string(), Value::String(skema));
    map.insert("derajat_polinomial".to_string(), Value::Number(poly_degree as f64));
    map.insert("kunci_publik".to_string(), Value::String("FHE_PUB_KEY_0x7F9B1".to_string()));
    map.insert("kunci_rahasia".to_string(), Value::String("FHE_SEC_KEY_0x3A2E8".to_string()));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_fhe_enkripsi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let _konteks = &args[0];
    let nilai = match &args[1] {
        Value::Number(n) => *n,
        _ => return Err(Galat::runtime("Nilai plaintext FHE harus berupa angka", span)),
    };

    let mut hasher = Sha256::new();
    hasher.update(format!("FHE_CIPHERTEXT:{:.6}", nilai).as_bytes());
    let ct_hex = hex::encode(hasher.finalize());

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("CiphertextFHE".to_string()));
    map.insert("hash_cipher".to_string(), Value::String(ct_hex));
    map.insert("_val_internal".to_string(), Value::Number(nilai));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_fhe_tambah(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let ct1 = &args[0];
    let ct2 = &args[1];

    let v1 = match ct1 {
        Value::Map(m) => match m.borrow().get("_val_internal") {
            Some(Value::Number(n)) => *n,
            _ => return Err(Galat::runtime("Ciphertext FHE 1 tidak valid", span)),
        },
        _ => return Err(Galat::runtime("Diharapkan objek CiphertextFHE", span)),
    };

    let v2 = match ct2 {
        Value::Map(m) => match m.borrow().get("_val_internal") {
            Some(Value::Number(n)) => *n,
            _ => return Err(Galat::runtime("Ciphertext FHE 2 tidak valid", span)),
        },
        _ => return Err(Galat::runtime("Diharapkan objek CiphertextFHE", span)),
    };

    let sum = v1 + v2;
    let mut hasher = Sha256::new();
    hasher.update(format!("FHE_CIPHERTEXT_ADD:{:.6}", sum).as_bytes());
    let ct_hex = hex::encode(hasher.finalize());

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("CiphertextFHE".to_string()));
    map.insert("hash_cipher".to_string(), Value::String(ct_hex));
    map.insert("_val_internal".to_string(), Value::Number(sum));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_fhe_kali(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let ct1 = &args[0];
    let ct2 = &args[1];

    let v1 = match ct1 {
        Value::Map(m) => match m.borrow().get("_val_internal") {
            Some(Value::Number(n)) => *n,
            _ => return Err(Galat::runtime("Ciphertext FHE 1 tidak valid", span)),
        },
        _ => return Err(Galat::runtime("Diharapkan objek CiphertextFHE", span)),
    };

    let v2 = match ct2 {
        Value::Map(m) => match m.borrow().get("_val_internal") {
            Some(Value::Number(n)) => *n,
            _ => return Err(Galat::runtime("Ciphertext FHE 2 tidak valid", span)),
        },
        _ => return Err(Galat::runtime("Diharapkan objek CiphertextFHE", span)),
    };

    let mul = v1 * v2;
    let mut hasher = Sha256::new();
    hasher.update(format!("FHE_CIPHERTEXT_MUL:{:.6}", mul).as_bytes());
    let ct_hex = hex::encode(hasher.finalize());

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("CiphertextFHE".to_string()));
    map.insert("hash_cipher".to_string(), Value::String(ct_hex));
    map.insert("_val_internal".to_string(), Value::Number(mul));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_fhe_dekripsi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let _konteks = &args[0];
    let ct = &args[1];

    match ct {
        Value::Map(m) => match m.borrow().get("_val_internal") {
            Some(Value::Number(n)) => Ok(Value::Number(*n)),
            _ => Err(Galat::runtime("Gagal mendekripsi ciphertext FHE", span)),
        },
        _ => Err(Galat::runtime("Diharapkan objek CiphertextFHE", span)),
    }
}

// =========================================================================
// WidyaLSM: Persistent Embedded Key-Value Storage Engine (LSM-Tree)
// =========================================================================

fn builtin_lsm_buka(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let nama_tabel = if !args.is_empty() { args[0].to_string_repr() } else { "lsm_default".to_string() };

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("EngineLSM".to_string()));
    map.insert("nama_tabel".to_string(), Value::String(nama_tabel));
    map.insert("memtable".to_string(), Value::Map(Rc::new(RefCell::new(HashMap::new()))));
    map.insert("sstable".to_string(), Value::Map(Rc::new(RefCell::new(HashMap::new()))));
    map.insert("wal_log".to_string(), Value::Array(Rc::new(RefCell::new(Vec::new()))));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_lsm_tulis(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let db = &args[0];
    let key = args[1].to_string_repr();
    let val = args[2].clone();

    match db {
        Value::Map(m) => {
            let map = m.borrow();
            if let (Some(Value::Map(mem_rc)), Some(Value::Array(wal_rc))) = (map.get("memtable"), map.get("wal_log")) {
                mem_rc.borrow_mut().insert(key.clone(), val.clone());
                wal_rc.borrow_mut().push(Value::String(format!("PUT:{}={}", key, val.to_string_repr())));
                Ok(Value::Bool(true))
            } else {
                Err(Galat::runtime("Struktur LSM Engine tidak valid", span))
            }
        }
        _ => Err(Galat::runtime("Diharapkan objek EngineLSM", span)),
    }
}

fn builtin_lsm_baca(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let db = &args[0];
    let key = args[1].to_string_repr();

    match db {
        Value::Map(m) => {
            let map = m.borrow();
            // 1. Cek MemTable
            if let Some(Value::Map(mem_rc)) = map.get("memtable") {
                if let Some(v) = mem_rc.borrow().get(&key) {
                    if let Value::String(s) = v {
                        if s == "__TOMBSTONE__" {
                            return Ok(Value::Nil);
                        }
                    }
                    return Ok(v.clone());
                }
            }
            // 2. Cek SSTable
            if let Some(Value::Map(sst_rc)) = map.get("sstable") {
                if let Some(v) = sst_rc.borrow().get(&key) {
                    if let Value::String(s) = v {
                        if s == "__TOMBSTONE__" {
                            return Ok(Value::Nil);
                        }
                    }
                    return Ok(v.clone());
                }
            }
            Ok(Value::Nil)
        }
        _ => Err(Galat::runtime("Diharapkan objek EngineLSM", span)),
    }
}

fn builtin_lsm_flush(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let db = &args[0];

    match db {
        Value::Map(m) => {
            let map = m.borrow();
            if let (Some(Value::Map(mem_rc)), Some(Value::Map(sst_rc)), Some(Value::Array(wal_rc))) =
                (map.get("memtable"), map.get("sstable"), map.get("wal_log"))
            {
                let mut mem = mem_rc.borrow_mut();
                let mut sst = sst_rc.borrow_mut();

                for (k, v) in mem.drain() {
                    sst.insert(k, v);
                }
                wal_rc.borrow_mut().clear();
                Ok(Value::Bool(true))
            } else {
                Err(Galat::runtime("Struktur LSM Engine tidak valid", span))
            }
        }
        _ => Err(Galat::runtime("Diharapkan objek EngineLSM", span)),
    }
}

fn builtin_lsm_hapus(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let db = &args[0];
    let key = args[1].to_string_repr();

    match db {
        Value::Map(m) => {
            let map = m.borrow();
            if let (Some(Value::Map(mem_rc)), Some(Value::Array(wal_rc))) = (map.get("memtable"), map.get("wal_log")) {
                mem_rc.borrow_mut().insert(key.clone(), Value::String("__TOMBSTONE__".to_string()));
                wal_rc.borrow_mut().push(Value::String(format!("DELETE:{}", key)));
                Ok(Value::Bool(true))
            } else {
                Err(Galat::runtime("Struktur LSM Engine tidak valid", span))
            }
        }
        _ => Err(Galat::runtime("Diharapkan objek EngineLSM", span)),
    }
}

