// WidyaAudio: DSP Digital Sound Synthesis & Web Audio Engine
// =========================================================================

fn builtin_audio_sintesis(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let sample_rate = if !args.is_empty() { match args[0] { Value::Number(n) => n, _ => 44100.0 } } else { 44100.0 };
    let durasi = if args.len() >= 2 { match args[1] { Value::Number(n) => n, _ => 1.0 } } else { 1.0 };

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("SintesisAudio".to_string()));
    map.insert("laju_sampel".to_string(), Value::Number(sample_rate));
    map.insert("durasi_detik".to_string(), Value::Number(durasi));
    map.insert("sampel".to_string(), Value::Array(Rc::new(RefCell::new(Vec::new()))));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_audio_buat_nada(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let freq = match args.first() {
        Some(Value::Number(n)) => *n,
        _ => return Err(Galat::runtime("Frekuensi nada harus berupa angka (Hz)", span)),
    };
    let gelombang = args.get(1).map(|v| v.to_string_repr()).unwrap_or_else(|| "SINUS".to_string());
    let durasi = args.get(2).and_then(|v| if let Value::Number(n) = v { Some(*n) } else { None }).unwrap_or(0.5);
    let ampl = args.get(3).and_then(|v| if let Value::Number(n) = v { Some(*n) } else { None }).unwrap_or(0.8);

    let sample_rate = 44100.0;
    let total_samples = (sample_rate * durasi) as usize;
    let mut samples = Vec::with_capacity(total_samples);

    for i in 0..total_samples {
        let t = i as f64 / sample_rate;
        let val = match gelombang.to_uppercase().as_str() {
            "SINUS" | "SINE" => (2.0 * std::f64::consts::PI * freq * t).sin() * ampl,
            "KOTAK" | "SQUARE" => if (2.0 * std::f64::consts::PI * freq * t).sin() >= 0.0 { ampl } else { -ampl },
            "SEGITIGA" | "TRIANGLE" => (2.0 / std::f64::consts::PI * (2.0 * std::f64::consts::PI * freq * t).sin().asin()) * ampl,
            "GERGAJI" | "SAWTOOTH" => (2.0 * (t * freq - (t * freq + 0.5).floor())) * ampl,
            _ => (2.0 * std::f64::consts::PI * freq * t).sin() * ampl,
        };
        samples.push(Value::Number(val));
    }

    Ok(Value::Array(Rc::new(RefCell::new(samples))))
}

fn builtin_audio_terapkan_adsr(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let samples_val = match &args[0] {
        Value::Array(arr) => arr.borrow().clone(),
        _ => return Err(Galat::runtime("Sampel audio harus berupa daftar angka", span)),
    };

    let attack = args.get(1).and_then(|v| if let Value::Number(n) = v { Some(*n) } else { None }).unwrap_or(0.1);
    let decay = args.get(2).and_then(|v| if let Value::Number(n) = v { Some(*n) } else { None }).unwrap_or(0.1);
    let sustain = args.get(3).and_then(|v| if let Value::Number(n) = v { Some(*n) } else { None }).unwrap_or(0.7);
    let release = args.get(4).and_then(|v| if let Value::Number(n) = v { Some(*n) } else { None }).unwrap_or(0.2);

    let n = samples_val.len() as f64;
    let a_end = (n * attack) as usize;
    let d_end = (n * (attack + decay)) as usize;
    let r_start = (n * (1.0 - release)) as usize;

    let total_len = samples_val.len();
    let mut out = Vec::with_capacity(total_len);
    for (i, sample) in samples_val.into_iter().enumerate() {
        let v = match sample { Value::Number(num) => num, _ => 0.0 };
        let env = if i < a_end {
            i as f64 / (a_end.max(1) as f64)
        } else if i < d_end {
            1.0 - (1.0 - sustain) * ((i - a_end) as f64 / ((d_end - a_end).max(1) as f64))
        } else if i < r_start {
            sustain
        } else {
            sustain * (1.0 - ((i - r_start) as f64 / ((total_len - r_start).max(1) as f64)))
        };
        out.push(Value::Number(v * env));
    }

    Ok(Value::Array(Rc::new(RefCell::new(out))))
}

fn builtin_audio_ekspor_wav(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let samples: Vec<f64> = match &args[0] {
        Value::Array(a) => a.borrow().iter().map(|v| match v { Value::Number(n) => *n, _ => 0.0 }).collect(),
        Value::Map(m) => {
            let map = m.borrow();
            if let Some(Value::Array(a)) = map.get("sampel") {
                a.borrow().iter().map(|v| match v { Value::Number(n) => *n, _ => 0.0 }).collect()
            } else {
                Vec::new()
            }
        }
        _ => return Err(Galat::runtime("Diharapkan buffer audio atau daftar sampel numerik", span)),
    };

    let filename = args[1].to_string_repr();
    let num_samples = samples.len() as u32;
    let sample_rate: u32 = 44100;
    let byte_rate = sample_rate * 2; // 16-bit mono = 2 bytes per sample

    let mut bytes: Vec<u8> = Vec::new();
    bytes.extend_from_slice(b"RIFF");
    bytes.extend_from_slice(&(36 + num_samples * 2).to_le_bytes());
    bytes.extend_from_slice(b"WAVE");
    bytes.extend_from_slice(b"fmt ");
    bytes.extend_from_slice(&16u32.to_le_bytes()); // Subchunk1Size
    bytes.extend_from_slice(&1u16.to_le_bytes()); // PCM
    bytes.extend_from_slice(&1u16.to_le_bytes()); // Mono
    bytes.extend_from_slice(&sample_rate.to_le_bytes());
    bytes.extend_from_slice(&byte_rate.to_le_bytes());
    bytes.extend_from_slice(&2u16.to_le_bytes()); // BlockAlign
    bytes.extend_from_slice(&16u16.to_le_bytes()); // BitsPerSample
    bytes.extend_from_slice(b"data");
    bytes.extend_from_slice(&(num_samples * 2).to_le_bytes());

    for s in samples {
        let pcm = (s.clamp(-1.0, 1.0) * 32767.0) as i16;
        bytes.extend_from_slice(&pcm.to_le_bytes());
    }

    let _ = fs::write(&filename, &bytes);
    Ok(Value::Bool(true))
}

fn builtin_audio_render_html(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let judul = args.get(1).map(|v| v.to_string_repr()).unwrap_or_else(|| "Widya DSP Web Audio Player".to_string());
    let html = format!(r#"<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>{}</title>
  <style>body {{ background: #0f172a; color: white; display: flex; justify-content: center; align-items: center; height: 100vh; font-family: sans-serif; }} .card {{ background: #1e293b; padding: 30px; border-radius: 16px; text-align: center; border: 1px solid #334155; }} button {{ background: #6366f1; color: white; border: none; padding: 12px 24px; border-radius: 8px; font-weight: bold; cursor: pointer; }}</style>
</head>
<body>
  <div class="card">
    <h2>🎵 {}</h2>
    <p>Synthesizer DSP Audio Generatif Widya-Lang</p>
    <button onclick="playTone()">▶️ Putar Gelombang Audio</button>
  </div>
  <script>
    function playTone() {{
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(440, ctx.currentTime);
      gain.gain.setValueAtTime(0.5, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 1.0);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 1.0);
    }}
  </script>
</body>
</html>"#, judul, judul);
    Ok(Value::String(html))
}

// =========================================================================
// WidyaTimeSeries: Time-Series Analytics & Forecasting Engine
// =========================================================================

fn builtin_timeseries_buat(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let nama = args[0].to_string_repr();
    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("DeretWaktu".to_string()));
    map.insert("nama".to_string(), Value::String(nama));
    map.insert("data_points".to_string(), Value::Array(Rc::new(RefCell::new(Vec::new()))));
    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_timeseries_tambah(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let ts = &args[0];
    let time = match args[1] { Value::Number(n) => n, _ => 0.0 };
    let val = match args[2] { Value::Number(n) => n, _ => 0.0 };

    match ts {
        Value::Map(m) => {
            let map = m.borrow();
            if let Some(Value::Array(arr)) = map.get("data_points") {
                let mut node = HashMap::new();
                node.insert("waktu".to_string(), Value::Number(time));
                node.insert("nilai".to_string(), Value::Number(val));
                arr.borrow_mut().push(Value::Map(Rc::new(RefCell::new(node))));
                Ok(Value::Bool(true))
            } else {
                Err(Galat::runtime("DeretWaktu tidak valid", span))
            }
        }
        _ => Err(Galat::runtime("Diharapkan objek DeretWaktu", span)),
    }
}

fn builtin_timeseries_sma(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let points = match &args[0] {
        Value::Array(a) => a.borrow().iter().map(|v| match v { Value::Number(n) => *n, _ => 0.0 }).collect::<Vec<f64>>(),
        Value::Map(m) => {
            let map = m.borrow();
            if let Some(Value::Array(a)) = map.get("data_points") {
                a.borrow().iter().map(|it| {
                    if let Value::Map(node) = it {
                        match node.borrow().get("nilai") { Some(Value::Number(n)) => *n, _ => 0.0 }
                    } else if let Value::Number(n) = it {
                        *n
                    } else {
                        0.0
                    }
                }).collect()
            } else {
                Vec::new()
            }
        }
        _ => return Err(Galat::runtime("Diharapkan objek DeretWaktu atau daftar angka", span)),
    };

    let window = match args[1] { Value::Number(n) => (n as usize).max(1), _ => 3 };
    let mut sma = Vec::new();

    for i in 0..points.len() {
        if i + 1 >= window {
            let start = i + 1 - window;
            let sum: f64 = points[start..=i].iter().sum();
            sma.push(Value::Number(sum / window as f64));
        } else {
            let sum: f64 = points[0..=i].iter().sum();
            sma.push(Value::Number(sum / (i + 1) as f64));
        }
    }

    Ok(Value::Array(Rc::new(RefCell::new(sma))))
}

fn builtin_timeseries_prediksi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let points: Vec<f64> = match &args[0] {
        Value::Array(a) => a.borrow().iter().map(|v| match v { Value::Number(n) => *n, _ => 0.0 }).collect(),
        Value::Map(m) => {
            let map = m.borrow();
            if let Some(Value::Array(a)) = map.get("data_points") {
                a.borrow().iter().map(|it| {
                    if let Value::Map(node) = it {
                        match node.borrow().get("nilai") { Some(Value::Number(n)) => *n, _ => 0.0 }
                    } else if let Value::Number(n) = it {
                        *n
                    } else {
                        0.0
                    }
                }).collect()
            } else {
                Vec::new()
            }
        }
        _ => return Err(Galat::runtime("Diharapkan objek DeretWaktu", span)),
    };

    let alpha = args.get(1).and_then(|v| if let Value::Number(n) = v { Some(*n) } else { None }).unwrap_or(0.3);
    let horizon = args.get(2).and_then(|v| if let Value::Number(n) = v { Some(*n as usize) } else { None }).unwrap_or(3);

    if points.is_empty() {
        return Ok(Value::Array(Rc::new(RefCell::new(Vec::new()))));
    }

    // Single Exponential Smoothing
    let mut smoothed = points[0];
    for &p in points.iter().skip(1) {
        smoothed = alpha * p + (1.0 - alpha) * smoothed;
    }

    let forecasts: Vec<Value> = (0..horizon).map(|_| Value::Number(smoothed)).collect();
    Ok(Value::Array(Rc::new(RefCell::new(forecasts))))
}

fn builtin_timeseries_anomali(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let points: Vec<f64> = match &args[0] {
        Value::Array(a) => a.borrow().iter().map(|v| match v { Value::Number(n) => *n, _ => 0.0 }).collect(),
        _ => return Err(Galat::runtime("Diharapkan daftar data numerik", span)),
    };

    let z_threshold = args.get(1).and_then(|v| if let Value::Number(n) = v { Some(*n) } else { None }).unwrap_or(2.0);
    if points.len() < 2 {
        return Ok(Value::Array(Rc::new(RefCell::new(Vec::new()))));
    }

    let mean = points.iter().sum::<f64>() / points.len() as f64;
    let variance = points.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / (points.len() - 1) as f64;
    let std_dev = variance.sqrt().max(1e-6);

    let mut anomalies = Vec::new();
    for (idx, &val) in points.iter().enumerate() {
        let z = ((val - mean) / std_dev).abs();
        if z >= z_threshold {
            let mut node = HashMap::new();
            node.insert("indeks".to_string(), Value::Number(idx as f64));
            node.insert("nilai".to_string(), Value::Number(val));
            node.insert("z_score".to_string(), Value::Number(z));
            anomalies.push(Value::Map(Rc::new(RefCell::new(node))));
        }
    }

    Ok(Value::Array(Rc::new(RefCell::new(anomalies))))
}

// =========================================================================
// WidyaBloom: Bloom Filter & HyperLogLog Probabilistic Big Data Engine
// =========================================================================

fn builtin_bloom_buat(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let capacity = args.first().and_then(|v| if let Value::Number(n) = v { Some(*n as usize) } else { None }).unwrap_or(1000);
    let size = (capacity * 10).max(64);

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("FilterBloom".to_string()));
    map.insert("ukuran_bit".to_string(), Value::Number(size as f64));
    map.insert("bitset".to_string(), Value::Array(Rc::new(RefCell::new(vec![Value::Bool(false); size]))));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_bloom_tambah(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let item = args[1].to_string_repr();
    match &args[0] {
        Value::Map(m) => {
            let map = m.borrow();
            let size = match map.get("ukuran_bit") { Some(Value::Number(n)) => *n as usize, _ => 64 };
            if let Some(Value::Array(bits_rc)) = map.get("bitset") {
                let mut bits = bits_rc.borrow_mut();
                for seed in [1337u64, 4242u64, 9999u64] {
                    let mut hasher = Sha256::new();
                    hasher.update(format!("{}:{}", seed, item).as_bytes());
                    let h = u64::from_le_bytes(hasher.finalize()[0..8].try_into().unwrap());
                    let idx = (h as usize) % size;
                    bits[idx] = Value::Bool(true);
                }
                Ok(Value::Bool(true))
            } else {
                Err(Galat::runtime("FilterBloom tidak valid", span))
            }
        }
        _ => Err(Galat::runtime("Diharapkan objek FilterBloom", span)),
    }
}

fn builtin_bloom_cek(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let item = args[1].to_string_repr();
    match &args[0] {
        Value::Map(m) => {
            let map = m.borrow();
            let size = match map.get("ukuran_bit") { Some(Value::Number(n)) => *n as usize, _ => 64 };
            if let Some(Value::Array(bits_rc)) = map.get("bitset") {
                let bits = bits_rc.borrow();
                for seed in [1337u64, 4242u64, 9999u64] {
                    let mut hasher = Sha256::new();
                    hasher.update(format!("{}:{}", seed, item).as_bytes());
                    let h = u64::from_le_bytes(hasher.finalize()[0..8].try_into().unwrap());
                    let idx = (h as usize) % size;
                    if !bits[idx].is_truthy() {
                        return Ok(Value::Bool(false)); // Pasti tidak ada
                    }
                }
                Ok(Value::Bool(true)) // Mungkin ada
            } else {
                Err(Galat::runtime("FilterBloom tidak valid", span))
            }
        }
        _ => Err(Galat::runtime("Diharapkan objek FilterBloom", span)),
    }
}

fn builtin_hll_buat(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let p = args.first().and_then(|v| if let Value::Number(n) = v { Some((*n as usize).clamp(4, 16)) } else { None }).unwrap_or(10);
    let m = 1 << p;

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("HyperLogLog".to_string()));
    map.insert("p".to_string(), Value::Number(p as f64));
    map.insert("m".to_string(), Value::Number(m as f64));
    map.insert("registers".to_string(), Value::Array(Rc::new(RefCell::new(vec![Value::Number(0.0); m]))));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_hll_tambah(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let item_str = args[1].to_string_repr();
    match &args[0] {
        Value::Map(m_rc) => {
            let map = m_rc.borrow();
            let p = match map.get("p") { Some(Value::Number(n)) => *n as usize, _ => 10 };
            let m = 1 << p;
            let regs_rc = match map.get("registers") { Some(Value::Array(a)) => a.clone(), _ => return Err(Galat::runtime("Objek HyperLogLog tidak valid", span)) };

            let mut hasher = Sha256::new();
            hasher.update(item_str.as_bytes());
            let hash_bytes = hasher.finalize();
            let hash_val = u64::from_le_bytes(hash_bytes[0..8].try_into().unwrap());

            let idx = (hash_val >> (64 - p)) as usize % m;
            let w = (hash_val << p) | (1 << (p - 1));
            let rank = (w.leading_zeros() + 1).min(64 - p as u32 + 1) as f64;

            let mut regs = regs_rc.borrow_mut();
            if let Some(Value::Number(curr)) = regs.get(idx) {
                if rank > *curr {
                    regs[idx] = Value::Number(rank);
                }
            }
            Ok(Value::Bool(true))
        }
        _ => Err(Galat::runtime("Fungsi hll_tambah memerlukan objek HyperLogLog", span)),
    }
}

fn builtin_hll_estimasi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    match &args[0] {
        Value::Map(m_rc) => {
            let map = m_rc.borrow();
            let p = match map.get("p") { Some(Value::Number(n)) => *n as usize, _ => 10 };
            let m = (1 << p) as f64;
            let regs_rc = match map.get("registers") { Some(Value::Array(a)) => a.clone(), _ => return Err(Galat::runtime("Objek HyperLogLog tidak valid", span)) };
            let regs = regs_rc.borrow();

            let alpha = match p {
                4 => 0.673,
                5 => 0.697,
                6 => 0.709,
                _ => 0.7213 / (1.0 + 1.079 / m),
            };

            let mut sum = 0.0;
            let mut zero_count = 0.0;
            for r in regs.iter() {
                let val = match r { Value::Number(n) => *n, _ => 0.0 };
                if val == 0.0 {
                    zero_count += 1.0;
                }
                sum += 2.0f64.powf(-val);
            }

            let mut raw_estimate = alpha * m * m / sum;
            if raw_estimate <= 2.5 * m && zero_count > 0.0 {
                raw_estimate = m * (m / zero_count).ln();
            }

            Ok(Value::Number(raw_estimate.round().max(0.0)))
        }
        _ => Err(Galat::runtime("Fungsi hll_estimasi memerlukan objek HyperLogLog", span)),
    }
}

fn builtin_hll_hitung(args: &[Value], span: &Span) -> Result<Value, Galat> {
    builtin_hll_estimasi(args, span)
}

fn builtin_hll_gabung(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let (p1, regs1) = match &args[0] {
        Value::Map(m) => {
            let map = m.borrow();
            let p = match map.get("p") { Some(Value::Number(n)) => *n as usize, _ => 10 };
            let a = match map.get("registers") { Some(Value::Array(a)) => a.clone(), _ => return Err(Galat::runtime("HLL 1 tidak valid", span)) };
            (p, a)
        }
        _ => return Err(Galat::runtime("Argumen 1 bukan HyperLogLog", span)),
    };
    let (p2, regs2) = match &args[1] {
        Value::Map(m) => {
            let map = m.borrow();
            let p = match map.get("p") { Some(Value::Number(n)) => *n as usize, _ => 10 };
            let a = match map.get("registers") { Some(Value::Array(a)) => a.clone(), _ => return Err(Galat::runtime("HLL 2 tidak valid", span)) };
            (p, a)
        }
        _ => return Err(Galat::runtime("Argumen 2 bukan HyperLogLog", span)),
    };

    if p1 != p2 {
        return Err(Galat::runtime("Dua objek HyperLogLog harus memiliki presisi p yang sama untuk digabung", span));
    }

    let m = 1 << p1;
    let r1 = regs1.borrow();
    let r2 = regs2.borrow();
    let mut new_regs = Vec::with_capacity(m);

    for i in 0..m {
        let v1 = match r1.get(i) { Some(Value::Number(n)) => *n, _ => 0.0 };
        let v2 = match r2.get(i) { Some(Value::Number(n)) => *n, _ => 0.0 };
        new_regs.push(Value::Number(v1.max(v2)));
    }

    let mut obj = HashMap::new();
    obj.insert("_tipe".to_string(), Value::String("HyperLogLog".to_string()));
    obj.insert("p".to_string(), Value::Number(p1 as f64));
    obj.insert("m".to_string(), Value::Number(m as f64));
    obj.insert("registers".to_string(), Value::Array(Rc::new(RefCell::new(new_regs))));
    Ok(Value::Map(Rc::new(RefCell::new(obj))))
}

// =========================================================================
// WidyaGraphEngine: Graph Theory, Topology & Pathfinding
// =========================================================================

fn builtin_graf_buat(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let berarah = args.first().map(|v| v.is_truthy()).unwrap_or(false);

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("GrafJaringan".to_string()));
    map.insert("berarah".to_string(), Value::Bool(berarah));
    map.insert("simpul".to_string(), Value::Map(Rc::new(RefCell::new(HashMap::new()))));
    map.insert("tetangga".to_string(), Value::Map(Rc::new(RefCell::new(HashMap::new()))));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_graf_tambah_simpul(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let id = args[1].to_string_repr();
    let meta = args.get(2).cloned().unwrap_or(Value::Nil);

    match &args[0] {
        Value::Map(m) => {
            let map = m.borrow();
            if let (Some(Value::Map(nodes_rc)), Some(Value::Map(adj_rc))) = (map.get("simpul"), map.get("tetangga")) {
                nodes_rc.borrow_mut().insert(id.clone(), meta);
                if !adj_rc.borrow().contains_key(&id) {
                    adj_rc.borrow_mut().insert(id, Value::Array(Rc::new(RefCell::new(Vec::new()))));
                }
                Ok(Value::Bool(true))
            } else {
                Err(Galat::runtime("GrafJaringan tidak valid", span))
            }
        }
        _ => Err(Galat::runtime("Diharapkan objek GrafJaringan", span)),
    }
}

fn builtin_graf_tambah_sisi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let u = args[1].to_string_repr();
    let v = args[2].to_string_repr();
    let bobot = args.get(3).and_then(|val| if let Value::Number(n) = val { Some(*n) } else { None }).unwrap_or(1.0);

    match &args[0] {
        Value::Map(m) => {
            let map = m.borrow();
            let berarah = map.get("berarah").map(|val| val.is_truthy()).unwrap_or(false);
            if let Some(Value::Map(adj_rc)) = map.get("tetangga") {
                let mut adj = adj_rc.borrow_mut();

                // Add u -> v
                let edge_uv = vec![Value::String(v.clone()), Value::Number(bobot)];
                adj.entry(u.clone())
                    .or_insert_with(|| Value::Array(Rc::new(RefCell::new(Vec::new()))));
                if let Some(Value::Array(a)) = adj.get(&u) {
                    a.borrow_mut().push(Value::Array(Rc::new(RefCell::new(edge_uv))));
                }

                // If undirected, add v -> u
                if !berarah {
                    let edge_vu = vec![Value::String(u.clone()), Value::Number(bobot)];
                    adj.entry(v.clone())
                        .or_insert_with(|| Value::Array(Rc::new(RefCell::new(Vec::new()))));
                    if let Some(Value::Array(a)) = adj.get(&v) {
                        a.borrow_mut().push(Value::Array(Rc::new(RefCell::new(edge_vu))));
                    }
                }
                Ok(Value::Bool(true))
            } else {
                Err(Galat::runtime("GrafJaringan tidak valid", span))
            }
        }
        _ => Err(Galat::runtime("Diharapkan objek GrafJaringan", span)),
    }
}

fn builtin_graf_dijkstra(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let start = args[1].to_string_repr();
    let target = args[2].to_string_repr();

    match &args[0] {
        Value::Map(m) => {
            let map = m.borrow();
            let adj_rc = match map.get("tetangga") {
                Some(Value::Map(m)) => m.borrow(),
                _ => return Err(Galat::runtime("GrafJaringan tidak valid", span)),
            };

            let mut dist: HashMap<String, f64> = HashMap::new();
            let mut prev: HashMap<String, String> = HashMap::new();
            let mut visited: HashMap<String, bool> = HashMap::new();

            for k in adj_rc.keys() {
                dist.insert(k.clone(), f64::INFINITY);
            }
            dist.insert(start.clone(), 0.0);

            loop {
                // Find unvisited node with min dist
                let mut min_node: Option<String> = None;
                let mut min_d = f64::INFINITY;

                for (node, &d) in dist.iter() {
                    if !visited.get(node).copied().unwrap_or(false) && d < min_d {
                        min_d = d;
                        min_node = Some(node.clone());
                    }
                }

                let current = match min_node {
                    Some(c) => c,
                    None => break,
                };

                if current == target || min_d == f64::INFINITY {
                    break;
                }

                visited.insert(current.clone(), true);

                if let Some(Value::Array(neighbors)) = adj_rc.get(&current) {
                    for edge in neighbors.borrow().iter() {
                        if let Value::Array(e_arr) = edge {
                            let e_items = e_arr.borrow();
                            let neighbor_id = e_items[0].to_string_repr();
                            let weight = match e_items[1] { Value::Number(n) => n, _ => 1.0 };

                            let alt = min_d + weight;
                            let cur_dist = dist.get(&neighbor_id).copied().unwrap_or(f64::INFINITY);
                            if alt < cur_dist {
                                dist.insert(neighbor_id.clone(), alt);
                                prev.insert(neighbor_id, current.clone());
                            }
                        }
                    }
                }
            }

            // Reconstruct path
            let total_cost = dist.get(&target).copied().unwrap_or(f64::INFINITY);
            let mut path = Vec::new();
            let mut curr = target.clone();

            if total_cost != f64::INFINITY {
                path.push(Value::String(curr.clone()));
                while let Some(p) = prev.get(&curr) {
                    path.push(Value::String(p.clone()));
                    curr = p.clone();
                }
                path.reverse();
            }

            let mut res = HashMap::new();
            res.insert("jarak_total".to_string(), Value::Number(if total_cost.is_infinite() { -1.0 } else { total_cost }));
            res.insert("jalur".to_string(), Value::Array(Rc::new(RefCell::new(path))));

            Ok(Value::Map(Rc::new(RefCell::new(res))))
        }
        _ => Err(Galat::runtime("Diharapkan objek GrafJaringan", span)),
    }
}

fn builtin_graf_pagerank(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let iterations = args.get(1).and_then(|v| if let Value::Number(n) = v { Some(*n as usize) } else { None }).unwrap_or(20);
    let damping = args.get(2).and_then(|v| if let Value::Number(n) = v { Some(*n) } else { None }).unwrap_or(0.85);

    match &args[0] {
        Value::Map(m) => {
            let map = m.borrow();
            let adj_rc = match map.get("tetangga") {
                Some(Value::Map(m)) => m.borrow(),
                _ => return Err(Galat::runtime("GrafJaringan tidak valid", span)),
            };

            let nodes: Vec<String> = adj_rc.keys().cloned().collect();
            let n = nodes.len();
            if n == 0 {
                return Ok(Value::Map(Rc::new(RefCell::new(HashMap::new()))));
            }

            let mut ranks: HashMap<String, f64> = nodes.iter().map(|k| (k.clone(), 1.0 / n as f64)).collect();

            for _ in 0..iterations {
                let mut next_ranks: HashMap<String, f64> = HashMap::new();
                for node in &nodes {
                    let mut incoming_score = 0.0;
                    for other in &nodes {
                        if let Some(Value::Array(edges)) = adj_rc.get(other) {
                            let out_degree = edges.borrow().len();
                            let is_connected = edges.borrow().iter().any(|e| {
                                if let Value::Array(e_arr) = e {
                                    e_arr.borrow()[0].to_string_repr() == *node
                                } else {
                                    false
                                }
                            });
                            if is_connected && out_degree > 0 {
                                incoming_score += ranks[other] / out_degree as f64;
                            }
                        }
                    }
                    next_ranks.insert(node.clone(), (1.0 - damping) / n as f64 + damping * incoming_score);
                }
                ranks = next_ranks;
            }

            let mut out = HashMap::new();
            for (k, v) in ranks {
                out.insert(k, Value::Number(v));
            }
            Ok(Value::Map(Rc::new(RefCell::new(out))))
        }
        _ => Err(Galat::runtime("Diharapkan objek GrafJaringan", span)),
    }
}

// ==============================================================================
// WidyaDiff: Myers Line & AST Diffing Engine & Unified Patch Generator
// ==============================================================================
fn myers_diff_lines(old_lines: &[&str], new_lines: &[&str]) -> Vec<(String, String)> {
    let n = old_lines.len();
    let m = new_lines.len();
    let max = n + m;
    let mut v = vec![0isize; 2 * max + 1];
    let mut trace = Vec::new();

    for d in 0..=(max as isize) {
        trace.push(v.clone());
        let mut k = -d;
        while k <= d {
            let mut x = if k == -d || (k != d && v[(k - 1 + max as isize) as usize] < v[(k + 1 + max as isize) as usize]) {
                v[(k + 1 + max as isize) as usize]
            } else {
                v[(k - 1 + max as isize) as usize] + 1
            };
            let mut y = x - k;

            while (x as usize) < n && (y as usize) < m && old_lines[x as usize] == new_lines[y as usize] {
                x += 1;
                y += 1;
            }

            v[(k + max as isize) as usize] = x;
            if x >= n as isize && y >= m as isize {
                break;
            }
            k += 2;
        }
        if v[(n as isize - m as isize + max as isize) as usize] >= n as isize {
            break;
        }
    }

    // Backtrack to find edits
    let mut x = n as isize;
    let mut y = m as isize;
    let mut edits = Vec::new();

    for (d, v_step) in trace.iter().enumerate().rev() {
        let k = x - y;
        let prev_k = if k == -(d as isize) || (k != (d as isize) && v_step[(k - 1 + max as isize) as usize] < v_step[(k + 1 + max as isize) as usize]) {
            k + 1
        } else {
            k - 1
        };
        let prev_x = v_step[(prev_k + max as isize) as usize];
        let prev_y = prev_x - prev_k;

        while x > prev_x && y > prev_y {
            edits.push((" ".to_string(), old_lines[(x - 1) as usize].to_string()));
            x -= 1;
            y -= 1;
        }

        if d > 0 {
            if x == prev_x {
                edits.push(("+".to_string(), new_lines[(y - 1) as usize].to_string()));
            } else if y == prev_y {
                edits.push(("-".to_string(), old_lines[(x - 1) as usize].to_string()));
            }
        }
        x = prev_x;
        y = prev_y;
    }

    edits.reverse();
    edits
}

fn builtin_diff_hitung(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let old_text = args[0].to_string_repr();
    let new_text = args[1].to_string_repr();

    let old_lines: Vec<&str> = old_text.lines().collect();
    let new_lines: Vec<&str> = new_text.lines().collect();

    let edits = myers_diff_lines(&old_lines, &new_lines);

    let mut result_items = Vec::new();
    let mut perubahancount = 0;

    for (tipe, baris) in edits {
        let mut item_map = HashMap::new();
        item_map.insert("tipe".to_string(), Value::String(tipe.clone()));
        item_map.insert("baris".to_string(), Value::String(baris));
        if tipe != " " {
            perubahancount += 1;
        }
        result_items.push(Value::Map(Rc::new(RefCell::new(item_map))));
    }

    let mut diff_obj = HashMap::new();
    diff_obj.insert("_tipe".to_string(), Value::String("WidyaDiff".to_string()));
    diff_obj.insert("perubahan".to_string(), Value::Array(Rc::new(RefCell::new(result_items))));
    diff_obj.insert("total_perubahan".to_string(), Value::Number(perubahancount as f64));
    diff_obj.insert("lama_len".to_string(), Value::Number(old_lines.len() as f64));
    diff_obj.insert("baru_len".to_string(), Value::Number(new_lines.len() as f64));

    Ok(Value::Map(Rc::new(RefCell::new(diff_obj))))
}

fn builtin_diff_format_patch(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let diff_val = &args[0];
    let file_name = args.get(1).map(|v| v.to_string_repr()).unwrap_or_else(|| "dokumen.wya".to_string());

    match diff_val {
        Value::Map(m) => {
            let map = m.borrow();
            let perubahan_rc = match map.get("perubahan") {
                Some(Value::Array(a)) => a.borrow(),
                _ => return Err(Galat::runtime("Objek WidyaDiff tidak memiliki array 'perubahan'", span)),
            };

            let mut patch_str = format!("--- a/{}\n+++ b/{}\n@@ -1,{} +1,{} @@\n",
                file_name, file_name,
                map.get("lama_len").and_then(|v| if let Value::Number(n) = v { Some(*n as usize) } else { None }).unwrap_or(1),
                map.get("baru_len").and_then(|v| if let Value::Number(n) = v { Some(*n as usize) } else { None }).unwrap_or(1)
            );

            for item in perubahan_rc.iter() {
                if let Value::Map(im) = item {
                    let im_map = im.borrow();
                    let t = im_map.get("tipe").map(|v| v.to_string_repr()).unwrap_or_else(|| " ".to_string());
                    let b = im_map.get("baris").map(|v| v.to_string_repr()).unwrap_or_default();
                    patch_str.push_str(&format!("{}{}\n", t, b));
                }
            }

            Ok(Value::String(patch_str))
        }
        _ => Err(Galat::runtime("Fungsi format_patch_terpadu memerlukan objek WidyaDiff", span)),
    }
}

fn builtin_diff_terapkan_patch(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let old_text = args[0].to_string_repr();
    let diff_val = &args[1];

    match diff_val {
        Value::Map(m) => {
            let map = m.borrow();
            let perubahan_rc = match map.get("perubahan") {
                Some(Value::Array(a)) => a.borrow(),
                _ => return Err(Galat::runtime("Objek WidyaDiff tidak valid", span)),
            };

            let mut new_lines = Vec::new();
            for item in perubahan_rc.iter() {
                if let Value::Map(im) = item {
                    let im_map = im.borrow();
                    let t = im_map.get("tipe").map(|v| v.to_string_repr()).unwrap_or_else(|| " ".to_string());
                    let b = im_map.get("baris").map(|v| v.to_string_repr()).unwrap_or_default();
                    if t == " " || t == "+" {
                        new_lines.push(b);
                    }
                }
            }
            Ok(Value::String(new_lines.join("\n")))
        }
        Value::String(patch_str) => {
            // Apply raw unified diff string
            let mut new_lines = Vec::new();
            for line in patch_str.lines() {
                if line.starts_with("---") || line.starts_with("+++") || line.starts_with("@@") {
                    continue;
                }
                if let Some(stripped) = line.strip_prefix('+') {
                    new_lines.push(stripped.to_string());
                } else if let Some(stripped) = line.strip_prefix(' ') {
                    new_lines.push(stripped.to_string());
                }
            }
            if new_lines.is_empty() {
                Ok(Value::String(old_text))
            } else {
                Ok(Value::String(new_lines.join("\n")))
            }
        }
        _ => Err(Galat::runtime("Argumen kedua harus berupa objek WidyaDiff atau string patch", span)),
    }
}

// ==============================================================================
// WidyaGenetic: Evolutionary Computing & Genetic Optimization
// ==============================================================================
fn builtin_ga_inisialisasi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let pop_size = match args[0] {
        Value::Number(n) => n.max(2.0) as usize,
        _ => return Err(Galat::runtime("Ukuran populasi harus angka", span)),
    };
    let chromosome_len = match args[1] {
        Value::Number(n) => n.max(1.0) as usize,
        _ => return Err(Galat::runtime("Panjang kromosom harus angka", span)),
    };

    let mut rng = rand::thread_rng();
    let mut population = Vec::new();

    for _ in 0..pop_size {
        let genes: Vec<Value> = (0..chromosome_len)
            .map(|_| Value::Number(if rng.r#gen::<bool>() { 1.0 } else { 0.0 }))
            .collect();
        population.push(Value::Array(Rc::new(RefCell::new(genes))));
    }

    let mut ga_obj = HashMap::new();
    ga_obj.insert("_tipe".to_string(), Value::String("WidyaGenetic".to_string()));
    ga_obj.insert("populasi".to_string(), Value::Array(Rc::new(RefCell::new(population))));
    ga_obj.insert("ukuran_populasi".to_string(), Value::Number(pop_size as f64));
    ga_obj.insert("panjang_kromosom".to_string(), Value::Number(chromosome_len as f64));
    ga_obj.insert("generasi".to_string(), Value::Number(0.0));

    Ok(Value::Map(Rc::new(RefCell::new(ga_obj))))
}

fn builtin_ga_evolusi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let ga_val = &args[0];
    let fitness_fn = &args[1];
    let mutation_rate = match args.get(2) {
        Some(Value::Number(n)) => *n,
        _ => 0.05,
    };
    let crossover_rate = match args.get(3) {
        Some(Value::Number(n)) => *n,
        _ => 0.8,
    };

    match ga_val {
        Value::Map(m) => {
            let mut map = m.borrow_mut();
            let pop_rc = match map.get("populasi") {
                Some(Value::Array(a)) => a.clone(),
                _ => return Err(Galat::runtime("Populasi GA tidak valid", span)),
            };

            let current_pop: Vec<Value> = pop_rc.borrow().clone();
            let pop_size = current_pop.len();
            if pop_size == 0 {
                return Ok(ga_val.clone());
            }

            // Calculate fitness scores
            let mut scored: Vec<(f64, Vec<f64>)> = Vec::new();
            for individual in &current_pop {
                let genes: Vec<f64> = if let Value::Array(arr) = individual {
                    arr.borrow().iter().map(|v| match v { Value::Number(n) => *n, _ => 0.0 }).collect()
                } else {
                    vec![]
                };

                let fitness_res = invoke_closure_or_fn(fitness_fn, &[individual.clone()], span)?;
                let fit_score = match fitness_res {
                    Value::Number(n) => n,
                    _ => 0.0,
                };
                scored.push((fit_score, genes));
            }

            // Sort descending by fitness
            scored.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal));
            let best_fitness = scored[0].0;
            let best_genes = scored[0].1.clone();

            let mut rng = rand::thread_rng();
            let mut next_pop = Vec::new();
            // Elitism: retain best individual
            let elite_vals: Vec<Value> = best_genes.iter().map(|&g| Value::Number(g)).collect();
            next_pop.push(Value::Array(Rc::new(RefCell::new(elite_vals))));

            let chromosome_len = scored[0].1.len();

            // Breed until full
            while next_pop.len() < pop_size {
                // Tournament selection (size 3)
                let mut pick = || {
                    let mut best_i = rng.gen_range(0..pop_size);
                    for _ in 0..2 {
                        let cand = rng.gen_range(0..pop_size);
                        if scored[cand].0 > scored[best_i].0 {
                            best_i = cand;
                        }
                    }
                    scored[best_i].1.clone()
                };

                let p1 = pick();
                let p2 = pick();

                // Crossover
                let mut child = if rng.r#gen::<f64>() < crossover_rate && chromosome_len > 1 {
                    let point = rng.gen_range(1..chromosome_len);
                    let mut c = p1[0..point].to_vec();
                    c.extend_from_slice(&p2[point..]);
                    c
                } else {
                    p1
                };

                // Mutation
                for gene in &mut child {
                    if rng.r#gen::<f64>() < mutation_rate {
                        *gene = if *gene == 0.0 { 1.0 } else { 0.0 };
                    }
                }

                let child_vals: Vec<Value> = child.into_iter().map(Value::Number).collect();
                next_pop.push(Value::Array(Rc::new(RefCell::new(child_vals))));
            }

            let gen_count = map.get("generasi").and_then(|v| if let Value::Number(n) = v { Some(*n + 1.0) } else { None }).unwrap_or(1.0);
            map.insert("populasi".to_string(), Value::Array(Rc::new(RefCell::new(next_pop))));
            map.insert("generasi".to_string(), Value::Number(gen_count));
            map.insert("fitness_terbaik".to_string(), Value::Number(best_fitness));
            let best_individual_vals: Vec<Value> = best_genes.into_iter().map(Value::Number).collect();
            map.insert("kromosom_terbaik".to_string(), Value::Array(Rc::new(RefCell::new(best_individual_vals))));

            Ok(ga_val.clone())
        }
        _ => Err(Galat::runtime("Fungsi evolusi_generasi_ga memerlukan objek WidyaGenetic", span)),
    }
}

fn builtin_ga_optimasi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let pop_size = match args[0] {
        Value::Number(n) => n.max(2.0) as usize,
        _ => return Err(Galat::runtime("Ukuran populasi harus angka", span)),
    };
    let chromosome_len = match args[1] {
        Value::Number(n) => n.max(1.0) as usize,
        _ => return Err(Galat::runtime("Panjang kromosom harus angka", span)),
    };
    let max_generations = match args[2] {
        Value::Number(n) => n.max(1.0) as usize,
        _ => 50,
    };
    let fitness_fn = &args[3];
    let target_fitness = args.get(4).and_then(|v| if let Value::Number(n) = v { Some(*n) } else { None });

    let ga_obj = builtin_ga_inisialisasi(&[Value::Number(pop_size as f64), Value::Number(chromosome_len as f64)], span)?;

    for _ in 0..max_generations {
        builtin_ga_evolusi(&[ga_obj.clone(), fitness_fn.clone(), Value::Number(0.05), Value::Number(0.8)], span)?;
        if let Value::Map(m) = &ga_obj {
            let map = m.borrow();
            if let Some(target) = target_fitness {
                if let Some(Value::Number(current_fit)) = map.get("fitness_terbaik") {
                    if *current_fit >= target {
                        break;
                    }
                }
            }
        }
    }

    Ok(ga_obj)
}

// ==============================================================================
// WidyaSemanticSearch: Vector Embeddings & Cosine Similarity Engine
// ==============================================================================
fn cosine_similarity_calc(a: &[f64], b: &[f64]) -> f64 {
    if a.len() != b.len() || a.is_empty() {
        return 0.0;
    }
    let mut dot = 0.0;
    let mut norm_a = 0.0;
    let mut norm_b = 0.0;

    for (x, y) in a.iter().zip(b.iter()) {
        dot += x * y;
        norm_a += x * x;
        norm_b += y * y;
    }

    if norm_a == 0.0 || norm_b == 0.0 {
        0.0
    } else {
        dot / (norm_a.sqrt() * norm_b.sqrt())
    }
}

fn builtin_vektor_cosine(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let extract_vec = |v: &Value| -> Result<Vec<f64>, Galat> {
        match v {
            Value::Array(a) => {
                let items = a.borrow();
                items.iter().map(|item| match item {
                    Value::Number(n) => Ok(*n),
                    _ => Err(Galat::runtime("Vektor harus berisi angka", span)),
                }).collect()
            }
            _ => Err(Galat::runtime("Diharapkan array vektor angka", span)),
        }
    };

    let v1 = extract_vec(&args[0])?;
    let v2 = extract_vec(&args[1])?;

    Ok(Value::Number(cosine_similarity_calc(&v1, &v2)))
}

fn builtin_vektor_buat_indeks(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let dim = args.first().and_then(|v| if let Value::Number(n) = v { Some(*n as usize) } else { None }).unwrap_or(0);

    let mut obj = HashMap::new();
    obj.insert("_tipe".to_string(), Value::String("IndeksVektor".to_string()));
    obj.insert("dimensi".to_string(), Value::Number(dim as f64));
    obj.insert("dokumen".to_string(), Value::Array(Rc::new(RefCell::new(Vec::new()))));

    Ok(Value::Map(Rc::new(RefCell::new(obj))))
}

fn builtin_vektor_tambah(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let index_val = &args[0];
    let doc_id = args[1].to_string_repr();
    let embedding = match &args[2] {
        Value::Array(a) => a.clone(),
        _ => return Err(Galat::runtime("Embedding harus berupa array angka", span)),
    };
    let metadata = args[3].clone();

    match index_val {
        Value::Map(m) => {
            let map = m.borrow();
            let docs_rc = match map.get("dokumen") {
                Some(Value::Array(a)) => a.clone(),
                _ => return Err(Galat::runtime("IndeksVektor tidak valid", span)),
            };

            let mut doc = HashMap::new();
            doc.insert("id".to_string(), Value::String(doc_id));
            doc.insert("vektor".to_string(), Value::Array(embedding));
            doc.insert("metadata".to_string(), metadata);

            docs_rc.borrow_mut().push(Value::Map(Rc::new(RefCell::new(doc))));
            Ok(Value::Bool(true))
        }
        _ => Err(Galat::runtime("Fungsi vektor_tambah memerlukan objek IndeksVektor", span)),
    }
}

fn builtin_vektor_kueri(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let index_val = &args[0];
    let query_embedding: Vec<f64> = match &args[1] {
        Value::Array(a) => {
            a.borrow().iter().map(|v| match v { Value::Number(n) => *n, _ => 0.0 }).collect()
        }
        _ => return Err(Galat::runtime("Kueri vektor harus berupa array angka", span)),
    };
    let top_k = match args.get(2) {
        Some(Value::Number(n)) => n.max(1.0) as usize,
        _ => 5,
    };

    match index_val {
        Value::Map(m) => {
            let map = m.borrow();
            let docs_rc = match map.get("dokumen") {
                Some(Value::Array(a)) => a.clone(),
                _ => return Err(Galat::runtime("IndeksVektor tidak valid", span)),
            };

            let mut scored: Vec<(f64, Value)> = Vec::new();
            for doc_val in docs_rc.borrow().iter() {
                if let Value::Map(dm) = doc_val {
                    let dmap = dm.borrow();
                    let doc_vec: Vec<f64> = match dmap.get("vektor") {
                        Some(Value::Array(va)) => va.borrow().iter().map(|v| match v { Value::Number(n) => *n, _ => 0.0 }).collect(),
                        _ => vec![],
                    };
                    let sim = cosine_similarity_calc(&query_embedding, &doc_vec);

                    let mut res_entry = HashMap::new();
                    res_entry.insert("id".to_string(), dmap.get("id").cloned().unwrap_or(Value::Nil));
                    res_entry.insert("kemiripan".to_string(), Value::Number(sim));
                    res_entry.insert("metadata".to_string(), dmap.get("metadata").cloned().unwrap_or(Value::Nil));

                    scored.push((sim, Value::Map(Rc::new(RefCell::new(res_entry)))));
                }
            }

            scored.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal));
            let top_results: Vec<Value> = scored.into_iter().take(top_k).map(|(_, v)| v).collect();

            Ok(Value::Array(Rc::new(RefCell::new(top_results))))
        }
        _ => Err(Galat::runtime("Fungsi vektor_kueri_kemiripan memerlukan objek IndeksVektor", span)),
    }
}

// ==============================================================================
// WidyaSmartContract: Deterministic State Machine & Ledger
// ==============================================================================
fn builtin_ledger_buat(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let mut init_saldo = HashMap::new();
    if let Some(Value::Map(init_m)) = args.first() {
        for (k, v) in init_m.borrow().iter() {
            init_saldo.insert(k.clone(), v.clone());
        }
    }

    let mut ledger = HashMap::new();
    ledger.insert("_tipe".to_string(), Value::String("BukuBesar".to_string()));
    ledger.insert("saldo".to_string(), Value::Map(Rc::new(RefCell::new(init_saldo))));
    ledger.insert("state_storage".to_string(), Value::Map(Rc::new(RefCell::new(HashMap::new()))));
    ledger.insert("riwayat_transaksi".to_string(), Value::Array(Rc::new(RefCell::new(Vec::new()))));

    Ok(Value::Map(Rc::new(RefCell::new(ledger))))
}

fn builtin_ledger_transfer(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let ledger_val = &args[0];
    let pengirim = args[1].to_string_repr();
    let penerima = args[2].to_string_repr();
    let jumlah = match args[3] {
        Value::Number(n) => {
            if n <= 0.0 {
                return Err(Galat::runtime("Jumlah transfer harus bernilai positif", span));
            }
            n
        }
        _ => return Err(Galat::runtime("Jumlah transfer harus berupa angka", span)),
    };

    match ledger_val {
        Value::Map(m) => {
            let map = m.borrow();
            let saldo_rc = match map.get("saldo") {
                Some(Value::Map(sm)) => sm.clone(),
                _ => return Err(Galat::runtime("BukuBesar tidak valid", span)),
            };

            let mut saldo_map = saldo_rc.borrow_mut();
            let saldo_pengirim = match saldo_map.get(&pengirim) {
                Some(Value::Number(n)) => *n,
                _ => 0.0,
            };

            if saldo_pengirim < jumlah {
                return Err(Galat::runtime(format!("Saldo tidak mencukupi: {} hanya memiliki {}", pengirim, saldo_pengirim), span));
            }

            let saldo_penerima = match saldo_map.get(&penerima) {
                Some(Value::Number(n)) => *n,
                _ => 0.0,
            };

            saldo_map.insert(pengirim.clone(), Value::Number(saldo_pengirim - jumlah));
            saldo_map.insert(penerima.clone(), Value::Number(saldo_penerima + jumlah));

            // Log history
            if let Some(Value::Array(hist_arr)) = map.get("riwayat_transaksi") {
                let mut tx = HashMap::new();
                tx.insert("tipe".to_string(), Value::String("TRANSFER".to_string()));
                tx.insert("dari".to_string(), Value::String(pengirim));
                tx.insert("ke".to_string(), Value::String(penerima));
                tx.insert("nilai".to_string(), Value::Number(jumlah));
                hist_arr.borrow_mut().push(Value::Map(Rc::new(RefCell::new(tx))));
            }

            Ok(Value::Bool(true))
        }
        _ => Err(Galat::runtime("Fungsi transfer_saldo_ledger memerlukan objek BukuBesar", span)),
    }
}

fn builtin_ledger_set_state(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let ledger_val = &args[0];
    let contract_addr = args[1].to_string_repr();
    let slot_key = args[2].to_string_repr();
    let val = args[3].clone();

    match ledger_val {
        Value::Map(m) => {
            let map = m.borrow();
            let state_rc = match map.get("state_storage") {
                Some(Value::Map(sm)) => sm.clone(),
                _ => return Err(Galat::runtime("BukuBesar tidak valid", span)),
            };

            let mut outer_map = state_rc.borrow_mut();
            let contract_map_val = outer_map.entry(contract_addr).or_insert_with(|| Value::Map(Rc::new(RefCell::new(HashMap::new()))));
            if let Value::Map(cm) = contract_map_val {
                cm.borrow_mut().insert(slot_key, val);
            }
            Ok(Value::Bool(true))
        }
        _ => Err(Galat::runtime("Fungsi ledger_set_state memerlukan objek BukuBesar", span)),
    }
}

fn builtin_ledger_get_state(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let ledger_val = &args[0];
    let contract_addr = args[1].to_string_repr();
    let slot_key = args[2].to_string_repr();

    match ledger_val {
        Value::Map(m) => {
            let map = m.borrow();
            let state_rc = match map.get("state_storage") {
                Some(Value::Map(sm)) => sm.borrow(),
                _ => return Err(Galat::runtime("BukuBesar tidak valid", span)),
            };

            if let Some(Value::Map(cm)) = state_rc.get(&contract_addr) {
                let cmap = cm.borrow();
                Ok(cmap.get(&slot_key).cloned().unwrap_or(Value::Nil))
            } else {
                Ok(Value::Nil)
            }
        }
        _ => Err(Galat::runtime("Fungsi ledger_get_state memerlukan objek BukuBesar", span)),
    }
}

fn builtin_ledger_eksekusi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let ledger_val = &args[0];
    let pengirim = args[1].to_string_repr();
    let kontrak = args[2].to_string_repr();
    let handler_fn = &args[3];
    let gas_limit = match args[4] {
        Value::Number(n) => n.max(10.0),
        _ => 100_000.0,
    };

    // Execute state handler closure
    let gas_price = 0.001;
    let gas_used = (gas_limit * 0.15).round(); // deterministic gas consumption
    let gas_fee = gas_used * gas_price;

    match ledger_val {
        Value::Map(m) => {
            let map = m.borrow();
            let saldo_rc = match map.get("saldo") {
                Some(Value::Map(sm)) => sm.clone(),
                _ => return Err(Galat::runtime("BukuBesar tidak valid", span)),
            };

            // Deduct gas
            {
                let mut saldo_map = saldo_rc.borrow_mut();
                let saldo_p = match saldo_map.get(&pengirim) {
                    Some(Value::Number(n)) => *n,
                    _ => 0.0,
                };
                if saldo_p < gas_fee {
                    return Err(Galat::runtime(format!("Gas tidak cukup: saldo {} < gas fee {}", saldo_p, gas_fee), span));
                }
                saldo_map.insert(pengirim.clone(), Value::Number(saldo_p - gas_fee));
            }

            // Call contract function handler
            let exec_result = invoke_closure_or_fn(handler_fn, &[ledger_val.clone(), Value::String(kontrak.clone()), Value::String(pengirim.clone())], span)?;

            let mut receipt = HashMap::new();
            receipt.insert("sukses".to_string(), Value::Bool(true));
            receipt.insert("kontrak".to_string(), Value::String(kontrak));
            receipt.insert("pengirim".to_string(), Value::String(pengirim));
            receipt.insert("gas_terpakai".to_string(), Value::Number(gas_used));
            receipt.insert("biaya_gas".to_string(), Value::Number(gas_fee));
            receipt.insert("hasil".to_string(), exec_result);

            Ok(Value::Map(Rc::new(RefCell::new(receipt))))
        }
        _ => Err(Galat::runtime("Fungsi eksekusi_transaksi_ledger memerlukan objek BukuBesar", span)),
    }
}

// ==============================================================================
// WidyaPhysics2D: Rigid Body Dynamics & Verlet Integration
// ==============================================================================
fn builtin_fisika_dunia(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let gx = args.first().and_then(|v| if let Value::Number(n) = v { Some(*n) } else { None }).unwrap_or(0.0);
    let gy = args.get(1).and_then(|v| if let Value::Number(n) = v { Some(*n) } else { None }).unwrap_or(9.8);

    let mut obj = HashMap::new();
    obj.insert("_tipe".to_string(), Value::String("DuniaFisika".to_string()));
    obj.insert("gravitasi_x".to_string(), Value::Number(gx));
    obj.insert("gravitasi_y".to_string(), Value::Number(gy));
    obj.insert("benda".to_string(), Value::Map(Rc::new(RefCell::new(HashMap::new()))));

    Ok(Value::Map(Rc::new(RefCell::new(obj))))
}

