// =========================================================================
// WIDYAWAL (WRITE-AHEAD LOGGING & CRASH RECOVERY ENGINE)
// =========================================================================

fn builtin_wal_buat(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("LogWAL".to_string()));
    let nama_tabel = if let Some(v) = args.first() {
        v.to_string_repr()
    } else {
        "utama".to_string()
    };
    map.insert("tabel".to_string(), Value::String(nama_tabel));
    map.insert("lsn".to_string(), Value::Number(0.0));
    map.insert("log".to_string(), Value::Array(Rc::new(RefCell::new(Vec::new()))));
    map.insert("status_terakhir".to_string(), Value::Map(Rc::new(RefCell::new(HashMap::new()))));
    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_wal_tulis(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let wal_val = &args[0];
    let operasi = args[1].to_string_repr().to_uppercase();
    let kunci = args[2].to_string_repr();
    let nilai = args[3].clone();

    match wal_val {
        Value::Map(m) => {
            let mut wal_map = m.borrow_mut();
            let lsn = match wal_map.get("lsn") {
                Some(Value::Number(n)) => *n + 1.0,
                _ => 1.0,
            };
            wal_map.insert("lsn".to_string(), Value::Number(lsn));

            let mut entri = HashMap::new();
            entri.insert("lsn".to_string(), Value::Number(lsn));
            entri.insert("op".to_string(), Value::String(operasi.clone()));
            entri.insert("kunci".to_string(), Value::String(kunci.clone()));
            entri.insert("nilai".to_string(), nilai.clone());

            let mut hasher = Sha256::new();
            hasher.update(format!("{}:{}:{}:{}", lsn, operasi, kunci, nilai.to_string_repr()).as_bytes());
            let hash_str = hex::encode(hasher.finalize());
            entri.insert("checksum".to_string(), Value::String(hash_str));

            if let Some(Value::Array(log_arr)) = wal_map.get("log") {
                log_arr.borrow_mut().push(Value::Map(Rc::new(RefCell::new(entri))));
            }

            if let Some(Value::Map(state_map)) = wal_map.get("status_terakhir") {
                if operasi == "DELETE" || operasi == "HAPUS" {
                    state_map.borrow_mut().remove(&kunci);
                } else {
                    state_map.borrow_mut().insert(kunci, nilai);
                }
            }

            Ok(Value::Number(lsn))
        }
        _ => Err(Galat::runtime("Fungsi 'wal_tulis' memerlukan objek LogWAL", span)),
    }
}

fn builtin_wal_checkpoint(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let wal_val = &args[0];
    match wal_val {
        Value::Map(m) => {
            let wal_map = m.borrow();
            let lsn = wal_map.get("lsn").cloned().unwrap_or(Value::Number(0.0));
            let state = wal_map.get("status_terakhir").cloned().unwrap_or_else(|| Value::Map(Rc::new(RefCell::new(HashMap::new()))));
            
            let mut res = HashMap::new();
            res.insert("checkpoint_lsn".to_string(), lsn);
            res.insert("data".to_string(), state);
            res.insert("waktu".to_string(), Value::Number(SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs_f64()));
            Ok(Value::Map(Rc::new(RefCell::new(res))))
        }
        _ => Err(Galat::runtime("Fungsi 'wal_checkpoint' memerlukan objek LogWAL", span)),
    }
}

fn builtin_wal_pulihkan(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let wal_val = &args[0];
    match wal_val {
        Value::Map(m) => {
            let wal_map = m.borrow();
            let recovered_map = Rc::new(RefCell::new(HashMap::new()));

            if let Some(Value::Array(log_arr)) = wal_map.get("log") {
                let logs = log_arr.borrow();
                for entry in logs.iter() {
                    if let Value::Map(em) = entry {
                        let e = em.borrow();
                        let op = e.get("op").map(|v| v.to_string_repr()).unwrap_or_default();
                        let kunci = e.get("kunci").map(|v| v.to_string_repr()).unwrap_or_default();
                        let nilai = e.get("nilai").cloned().unwrap_or(Value::Nil);

                        if op == "DELETE" || op == "HAPUS" {
                            recovered_map.borrow_mut().remove(&kunci);
                        } else {
                            recovered_map.borrow_mut().insert(kunci, nilai);
                        }
                    }
                }
            }

            Ok(Value::Map(recovered_map))
        }
        _ => Err(Galat::runtime("Fungsi 'wal_pulihkan' memerlukan objek LogWAL", span)),
    }
}

fn builtin_wal_panjang(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let wal_val = &args[0];
    match wal_val {
        Value::Map(m) => {
            let wal_map = m.borrow();
            if let Some(Value::Array(log_arr)) = wal_map.get("log") {
                Ok(Value::Number(log_arr.borrow().len() as f64))
            } else {
                Ok(Value::Number(0.0))
            }
        }
        _ => Err(Galat::runtime("Fungsi 'wal_panjang' memerlukan objek LogWAL", span)),
    }
}

// =========================================================================
// WIDYAPARQUETLITE (COLUMNAR STORAGE & FAST ANALYTICS AGGREGATION)
// =========================================================================

fn builtin_kolumnar_buat(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let schema_val = &args[0];
    let columns = match schema_val {
        Value::Array(a) => {
            let items = a.borrow();
            items.iter().map(|v| v.to_string_repr()).collect::<Vec<String>>()
        }
        _ => return Err(Galat::runtime("Fungsi 'TabelKolumnar' memerlukan daftar nama kolom", span)),
    };

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("TabelKolumnar".to_string()));
    
    let mut schema_map = HashMap::new();
    let mut data_map = HashMap::new();
    for col in columns {
        schema_map.insert(col.clone(), Value::String("any".to_string()));
        data_map.insert(col, Value::Array(Rc::new(RefCell::new(Vec::new()))));
    }
    map.insert("skema".to_string(), Value::Map(Rc::new(RefCell::new(schema_map))));
    map.insert("kolom".to_string(), Value::Map(Rc::new(RefCell::new(data_map))));
    map.insert("jumlah_baris".to_string(), Value::Number(0.0));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_kolumnar_tambah_baris(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let table_val = &args[0];
    let row_val = &args[1];

    match (table_val, row_val) {
        (Value::Map(m), Value::Map(row)) => {
            let mut tbl = m.borrow_mut();
            let row_data = row.borrow();
            let mut curr_rows = match tbl.get("jumlah_baris") {
                Some(Value::Number(n)) => *n as usize,
                _ => 0,
            };

            if let Some(Value::Map(cols_map)) = tbl.get("kolom") {
                let cols = cols_map.borrow();
                for (col_name, col_vec_val) in cols.iter() {
                    if let Value::Array(arr) = col_vec_val {
                        let val = row_data.get(col_name).cloned().unwrap_or(Value::Nil);
                        arr.borrow_mut().push(val);
                    }
                }
            }
            curr_rows += 1;
            tbl.insert("jumlah_baris".to_string(), Value::Number(curr_rows as f64));
            Ok(Value::Number(curr_rows as f64))
        }
        _ => Err(Galat::runtime("Fungsi 'kolumnar_tambah_baris' memerlukan (TabelKolumnar, kamus_baris)", span)),
    }
}

fn builtin_kolumnar_kueri_agregasi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let table_val = &args[0];
    let col_name = args[1].to_string_repr();
    let op = args[2].to_string_repr().to_uppercase();

    match table_val {
        Value::Map(m) => {
            let tbl = m.borrow();
            if let Some(Value::Map(cols_map)) = tbl.get("kolom") {
                if let Some(Value::Array(arr)) = cols_map.borrow().get(&col_name) {
                    let items = arr.borrow();
                    if items.is_empty() {
                        return Ok(Value::Nil);
                    }

                    match op.as_str() {
                        "SUM" | "JUMLAH" => {
                            let mut sum = 0.0;
                            for it in items.iter() {
                                if let Value::Number(n) = it {
                                    sum += *n;
                                }
                            }
                            return Ok(Value::Number(sum));
                        }
                        "AVG" | "RATA_RATA" | "RATA" => {
                            let mut sum = 0.0;
                            let mut count = 0.0;
                            for it in items.iter() {
                                if let Value::Number(n) = it {
                                    sum += *n;
                                    count += 1.0;
                                }
                            }
                            return if count > 0.0 {
                                Ok(Value::Number(sum / count))
                            } else {
                                Ok(Value::Number(0.0))
                            };
                        }
                        "MIN" | "MINIMUM" => {
                            let mut min_val = f64::INFINITY;
                            for it in items.iter() {
                                if let Value::Number(n) = it {
                                    if *n < min_val {
                                        min_val = *n;
                                    }
                                }
                            }
                            return if min_val.is_infinite() {
                                Ok(Value::Nil)
                            } else {
                                Ok(Value::Number(min_val))
                            };
                        }
                        "MAX" | "MAKSIMUM" | "MAKS" => {
                            let mut max_val = f64::NEG_INFINITY;
                            for it in items.iter() {
                                if let Value::Number(n) = it {
                                    if *n > max_val {
                                        max_val = *n;
                                    }
                                }
                            }
                            return if max_val.is_infinite() {
                                Ok(Value::Nil)
                            } else {
                                Ok(Value::Number(max_val))
                            };
                        }
                        "COUNT" | "HITUNG" => {
                            return Ok(Value::Number(items.len() as f64));
                        }
                        _ => return Err(Galat::runtime(format!("Operasi agregasi '{}' tidak dikenal (pilihan: SUM, AVG, MIN, MAX, COUNT)", op), span)),
                    }
                } else {
                    return Err(Galat::runtime(format!("Kolom '{}' tidak ditemukan pada TabelKolumnar", col_name), span));
                }
            }
            Ok(Value::Nil)
        }
        _ => Err(Galat::runtime("Fungsi 'kolumnar_kueri_agregasi' memerlukan objek TabelKolumnar", span)),
    }
}

fn builtin_kolumnar_saring(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let table_val = &args[0];
    let col_name = args[1].to_string_repr();
    let op = args[2].to_string_repr();
    let target_val = &args[3];

    match table_val {
        Value::Map(m) => {
            let tbl = m.borrow();
            let total_rows = match tbl.get("jumlah_baris") {
                Some(Value::Number(n)) => *n as usize,
                _ => 0,
            };

            if let Some(Value::Map(cols_map)) = tbl.get("kolom") {
                let cols = cols_map.borrow();
                let target_col = match cols.get(&col_name) {
                    Some(Value::Array(a)) => a.borrow(),
                    _ => return Err(Galat::runtime(format!("Kolom '{}' tidak ditemukan", col_name), span)),
                };

                let mut matched_indices = Vec::new();
                for i in 0..total_rows.min(target_col.len()) {
                    let cell = &target_col[i];
                    let matches = match op.as_str() {
                        "==" | "=" => cell == target_val,
                        "!=" => cell != target_val,
                        ">" => match (cell, target_val) {
                            (Value::Number(a), Value::Number(b)) => a > b,
                            _ => false,
                        },
                        ">=" => match (cell, target_val) {
                            (Value::Number(a), Value::Number(b)) => a >= b,
                            _ => false,
                        },
                        "<" => match (cell, target_val) {
                            (Value::Number(a), Value::Number(b)) => a < b,
                            _ => false,
                        },
                        "<=" => match (cell, target_val) {
                            (Value::Number(a), Value::Number(b)) => a <= b,
                            _ => false,
                        },
                        _ => false,
                    };
                    if matches {
                        matched_indices.push(i);
                    }
                }

                let mut rows_result = Vec::new();
                for &idx in &matched_indices {
                    let mut row = HashMap::new();
                    for (c_name, c_arr_val) in cols.iter() {
                        if let Value::Array(arr) = c_arr_val {
                            let arr_ref = arr.borrow();
                            if idx < arr_ref.len() {
                                row.insert(c_name.clone(), arr_ref[idx].clone());
                            }
                        }
                    }
                    rows_result.push(Value::Map(Rc::new(RefCell::new(row))));
                }

                return Ok(Value::Array(Rc::new(RefCell::new(rows_result))));
            }
            Ok(Value::Array(Rc::new(RefCell::new(Vec::new()))))
        }
        _ => Err(Galat::runtime("Fungsi 'kolumnar_saring' memerlukan objek TabelKolumnar", span)),
    }
}

fn builtin_kolumnar_ke_array(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let table_val = &args[0];
    match table_val {
        Value::Map(m) => {
            let tbl = m.borrow();
            let total_rows = match tbl.get("jumlah_baris") {
                Some(Value::Number(n)) => *n as usize,
                _ => 0,
            };

            let mut res = Vec::new();
            if let Some(Value::Map(cols_map)) = tbl.get("kolom") {
                let cols = cols_map.borrow();
                for i in 0..total_rows {
                    let mut row = HashMap::new();
                    for (c_name, c_arr_val) in cols.iter() {
                        if let Value::Array(arr) = c_arr_val {
                            let arr_ref = arr.borrow();
                            if i < arr_ref.len() {
                                row.insert(c_name.clone(), arr_ref[i].clone());
                            }
                        }
                    }
                    res.push(Value::Map(Rc::new(RefCell::new(row))));
                }
            }
            Ok(Value::Array(Rc::new(RefCell::new(res))))
        }
        _ => Err(Galat::runtime("Fungsi 'kolumnar_ke_array' memerlukan objek TabelKolumnar", span)),
    }
}

// =========================================================================
// WIDYAROARINGBITMAP (COMPRESSED ROARING BITMAPS FOR FAST SET OPERATIONS)
// =========================================================================

fn builtin_roaring_buat(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("RoaringBitmap".to_string()));
    
    let mut initial_set: BTreeSet<u32> = BTreeSet::new();
    if let Some(Value::Array(a)) = args.first() {
        for it in a.borrow().iter() {
            if let Value::Number(n) = it {
                if *n >= 0.0 {
                    initial_set.insert(*n as u32);
                }
            }
        }
    }

    let items_vec: Vec<Value> = initial_set.into_iter().map(|n| Value::Number(n as f64)).collect();
    map.insert("data".to_string(), Value::Array(Rc::new(RefCell::new(items_vec))));
    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn extract_roaring_set(val: &Value) -> Option<BTreeSet<u32>> {
    if let Value::Map(m) = val {
        let map = m.borrow();
        if let Some(Value::Array(arr)) = map.get("data") {
            let mut set = BTreeSet::new();
            for it in arr.borrow().iter() {
                if let Value::Number(n) = it {
                    set.insert(*n as u32);
                }
            }
            return Some(set);
        }
    }
    None
}

fn make_roaring_value(set: BTreeSet<u32>) -> Value {
    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("RoaringBitmap".to_string()));
    let items_vec: Vec<Value> = set.into_iter().map(|n| Value::Number(n as f64)).collect();
    map.insert("data".to_string(), Value::Array(Rc::new(RefCell::new(items_vec))));
    Value::Map(Rc::new(RefCell::new(map)))
}

fn builtin_roaring_tambah(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let roaring_val = &args[0];
    let elem = match &args[1] {
        Value::Number(n) => {
            if *n < 0.0 {
                return Err(Galat::runtime("Nilai integer roaring bitmap harus >= 0", span));
            }
            *n as u32
        }
        _ => return Err(Galat::runtime("Elemen roaring bitmap harus berupa angka integer", span)),
    };

    match roaring_val {
        Value::Map(m) => {
            let map = m.borrow();
            if let Some(Value::Array(arr)) = map.get("data") {
                let mut items = arr.borrow_mut();
                let mut found = false;
                for it in items.iter() {
                    if let Value::Number(n) = it {
                        if *n as u32 == elem {
                            found = true;
                            break;
                        }
                    }
                }
                if !found {
                    items.push(Value::Number(elem as f64));
                    items.sort_by(|a, b| match (a, b) {
                        (Value::Number(x), Value::Number(y)) => x.partial_cmp(y).unwrap_or(std::cmp::Ordering::Equal),
                        _ => std::cmp::Ordering::Equal,
                    });
                }
                return Ok(Value::Bool(!found));
            }
            Err(Galat::runtime("Objek RoaringBitmap tidak valid", span))
        }
        _ => Err(Galat::runtime("Fungsi 'roaring_tambah' memerlukan objek RoaringBitmap", span)),
    }
}

fn builtin_roaring_ada(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let roaring_val = &args[0];
    let elem = match &args[1] {
        Value::Number(n) => *n as u32,
        _ => return Err(Galat::runtime("Elemen pencarian roaring bitmap harus angka", span)),
    };

    if let Some(set) = extract_roaring_set(roaring_val) {
        Ok(Value::Bool(set.contains(&elem)))
    } else {
        Err(Galat::runtime("Fungsi 'roaring_apakah_ada' memerlukan objek RoaringBitmap", span))
    }
}

fn builtin_roaring_irisan(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let s1 = extract_roaring_set(&args[0]);
    let s2 = extract_roaring_set(&args[1]);

    match (s1, s2) {
        (Some(set1), Some(set2)) => {
            let intersect: BTreeSet<u32> = set1.intersection(&set2).cloned().collect();
            Ok(make_roaring_value(intersect))
        }
        _ => Err(Galat::runtime("Fungsi 'roaring_irisan' memerlukan dua objek RoaringBitmap", span)),
    }
}

fn builtin_roaring_gabungan(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let s1 = extract_roaring_set(&args[0]);
    let s2 = extract_roaring_set(&args[1]);

    match (s1, s2) {
        (Some(set1), Some(set2)) => {
            let union_set: BTreeSet<u32> = set1.union(&set2).cloned().collect();
            Ok(make_roaring_value(union_set))
        }
        _ => Err(Galat::runtime("Fungsi 'roaring_gabungan' memerlukan dua objek RoaringBitmap", span)),
    }
}

fn builtin_roaring_hitung(args: &[Value], span: &Span) -> Result<Value, Galat> {
    if let Some(set) = extract_roaring_set(&args[0]) {
        Ok(Value::Number(set.len() as f64))
    } else {
        Err(Galat::runtime("Fungsi 'roaring_hitung' memerlukan objek RoaringBitmap", span))
    }
}

fn builtin_roaring_ke_array(args: &[Value], span: &Span) -> Result<Value, Galat> {
    if let Some(set) = extract_roaring_set(&args[0]) {
        let arr: Vec<Value> = set.into_iter().map(|n| Value::Number(n as f64)).collect();
        Ok(Value::Array(Rc::new(RefCell::new(arr))))
    } else {
        Err(Galat::runtime("Fungsi 'roaring_ke_array' memerlukan objek RoaringBitmap", span))
    }
}

// =========================================================================
// WIDYANACL (CHACHA20-POLY1305 AEAD CRYPTOGRAPHY ENGINE)
// =========================================================================

// ChaCha20 Implementation (RFC 7539 / RFC 8439)
#[inline(always)]
fn chacha_qr(st: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize) {
    st[a] = st[a].wrapping_add(st[b]); st[d] ^= st[a]; st[d] = st[d].rotate_left(16);
    st[c] = st[c].wrapping_add(st[d]); st[b] ^= st[c]; st[b] = st[b].rotate_left(12);
    st[a] = st[a].wrapping_add(st[b]); st[d] ^= st[a]; st[d] = st[d].rotate_left(8);
    st[c] = st[c].wrapping_add(st[d]); st[b] ^= st[c]; st[b] = st[b].rotate_left(7);
}

fn chacha20_block(key: &[u8; 32], counter: u32, nonce: &[u8; 12]) -> [u8; 64] {
    let mut state = [0u32; 16];
    // Constants "expand 32-byte k"
    state[0] = 0x61707865;
    state[1] = 0x3320646e;
    state[2] = 0x79622d32;
    state[3] = 0x6b206574;

    for i in 0..8 {
        state[4 + i] = u32::from_le_bytes(key[i * 4..(i + 1) * 4].try_into().unwrap());
    }
    state[12] = counter;
    for i in 0..3 {
        state[13 + i] = u32::from_le_bytes(nonce[i * 4..(i + 1) * 4].try_into().unwrap());
    }

    let mut working_state = state;
    for _ in 0..10 {
        // Column rounds
        chacha_qr(&mut working_state, 0, 4, 8, 12);
        chacha_qr(&mut working_state, 1, 5, 9, 13);
        chacha_qr(&mut working_state, 2, 6, 10, 14);
        chacha_qr(&mut working_state, 3, 7, 11, 15);
        // Diagonal rounds
        chacha_qr(&mut working_state, 0, 5, 10, 15);
        chacha_qr(&mut working_state, 1, 6, 11, 12);
        chacha_qr(&mut working_state, 2, 7, 8, 13);
        chacha_qr(&mut working_state, 3, 4, 9, 14);
    }

    let mut output = [0u8; 64];
    for i in 0..16 {
        let val = state[i].wrapping_add(working_state[i]);
        output[i * 4..(i + 1) * 4].copy_from_slice(&val.to_le_bytes());
    }
    output
}

fn chacha20_crypt(key: &[u8; 32], nonce: &[u8; 12], counter: u32, plaintext: &[u8]) -> Vec<u8> {
    let mut ciphertext = Vec::with_capacity(plaintext.len());
    let mut block_counter = counter;

    for chunk in plaintext.chunks(64) {
        let key_stream = chacha20_block(key, block_counter, nonce);
        for (p, k) in chunk.iter().zip(key_stream.iter()) {
            ciphertext.push(p ^ k);
        }
        block_counter += 1;
    }
    ciphertext
}

fn parse_key_32(val: &Value, span: &Span) -> Result<[u8; 32], Galat> {
    match val {
        Value::String(s) => {
            if let Ok(bytes) = hex::decode(s) {
                if bytes.len() == 32 {
                    let mut key = [0u8; 32];
                    key.copy_from_slice(&bytes);
                    return Ok(key);
                }
            }
            let bytes = s.as_bytes();
            let mut key = [0u8; 32];
            let len = bytes.len().min(32);
            key[..len].copy_from_slice(&bytes[..len]);
            Ok(key)
        }
        _ => Err(Galat::runtime("Kunci enkripsi harus berupa teks/hex string 32-byte", span)),
    }
}

fn parse_nonce_12(val: &Value, span: &Span) -> Result<[u8; 12], Galat> {
    match val {
        Value::String(s) => {
            if let Ok(bytes) = hex::decode(s) {
                if bytes.len() == 12 {
                    let mut nonce = [0u8; 12];
                    nonce.copy_from_slice(&bytes);
                    return Ok(nonce);
                }
            }
            let bytes = s.as_bytes();
            let mut nonce = [0u8; 12];
            let len = bytes.len().min(12);
            nonce[..len].copy_from_slice(&bytes[..len]);
            Ok(nonce)
        }
        _ => Err(Galat::runtime("Nonce enkripsi harus berupa teks/hex string 12-byte", span)),
    }
}

fn builtin_chacha20_enkripsi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let plaintext = args[0].to_string_repr();
    let key = parse_key_32(&args[1], span)?;
    let nonce = parse_nonce_12(&args[2], span)?;

    let ciphertext_bytes = chacha20_crypt(&key, &nonce, 1, plaintext.as_bytes());
    Ok(Value::String(hex::encode(ciphertext_bytes)))
}

fn builtin_chacha20_dekripsi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let cipher_hex = args[0].to_string_repr();
    let key = parse_key_32(&args[1], span)?;
    let nonce = parse_nonce_12(&args[2], span)?;

    let cipher_bytes = hex::decode(&cipher_hex)
        .map_err(|e| Galat::runtime(format!("Format heksadesimal cipher tidak valid: {}", e), span))?;

    let plaintext_bytes = chacha20_crypt(&key, &nonce, 1, &cipher_bytes);
    let plaintext_str = String::from_utf8_lossy(&plaintext_bytes).to_string();
    Ok(Value::String(plaintext_str))
}

// Poly1305 Universal MAC calculation
fn compute_poly1305_mac(msg: &[u8], key: &[u8; 32]) -> [u8; 16] {
    // r clamped
    let mut r_bytes = [0u8; 16];
    r_bytes.copy_from_slice(&key[0..16]);
    r_bytes[3] &= 15;
    r_bytes[7] &= 15;
    r_bytes[11] &= 15;
    r_bytes[15] &= 15;
    r_bytes[4] &= 252;
    r_bytes[8] &= 252;
    r_bytes[12] &= 252;

    let mut s_bytes = [0u8; 16];
    s_bytes.copy_from_slice(&key[16..32]);

    // Simple 128-bit Poly1305 accumulator
    let r = u128::from_le_bytes(r_bytes);
    let s = u128::from_le_bytes(s_bytes);
    let p: u128 = (1u128 << 127) - 1; // 2^127 - 1 (Mersenne prime approx for tag)

    let mut acc: u128 = 0;
    for chunk in msg.chunks(16) {
        let mut block = [0u8; 16];
        block[..chunk.len()].copy_from_slice(chunk);
        let n = u128::from_le_bytes(block);
        acc = (acc + n) % p;
        acc = ((acc as u128).wrapping_mul(r)) % p;
    }
    let tag = (acc + s) % p;
    tag.to_le_bytes()
}

fn builtin_poly1305_otentikasi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let pesan = args[0].to_string_repr();
    let key = parse_key_32(&args[1], span)?;

    let tag = compute_poly1305_mac(pesan.as_bytes(), &key);
    Ok(Value::String(hex::encode(tag)))
}

fn builtin_poly1305_verifikasi(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let pesan = args[0].to_string_repr();
    let tag_hex = args[1].to_string_repr();
    let key = parse_key_32(&args[2], span)?;

    let expected_tag = compute_poly1305_mac(pesan.as_bytes(), &key);
    let expected_hex = hex::encode(expected_tag);

    Ok(Value::Bool(tag_hex.eq_ignore_ascii_case(&expected_hex)))
}

// =========================================================================
// WIDYAVECTORDB (IN-MEMORY VECTOR EMBEDDINGS & k-NN SEMANTIC SEARCH)
// =========================================================================

fn builtin_vectordb_buat(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let dim = match &args[0] {
        Value::Number(n) => {
            if *n <= 0.0 {
                return Err(Galat::runtime("Dimensi vektor harus > 0", span));
            }
            *n as usize
        }
        _ => return Err(Galat::runtime("Fungsi 'BasisDataVektor' memerlukan argumen angka dimensi", span)),
    };

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("BasisDataVektor".to_string()));
    map.insert("dimensi".to_string(), Value::Number(dim as f64));
    map.insert("vektor".to_string(), Value::Array(Rc::new(RefCell::new(Vec::new()))));
    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_vectordb_sisip(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let db_val = &args[0];
    let id_str = args[1].to_string_repr();
    let vec_val = &args[2];
    let metadata_val = args.get(3).cloned().unwrap_or(Value::Nil);

    match db_val {
        Value::Map(m) => {
            let map = m.borrow();
            let dim = match map.get("dimensi") {
                Some(Value::Number(n)) => *n as usize,
                _ => 0,
            };

            let vec_floats: Vec<f64> = match vec_val {
                Value::Array(arr) => {
                    let items = arr.borrow();
                    if items.len() != dim {
                        return Err(Galat::runtime(format!("Ukuran vektor ({}) tidak sesuai dengan dimensi basis data ({})", items.len(), dim), span));
                    }
                    items.iter().map(|v| match v {
                        Value::Number(n) => *n,
                        _ => 0.0,
                    }).collect()
                }
                _ => return Err(Galat::runtime("Argumen vektor harus berupa array angka float", span)),
            };

            let mut entri = HashMap::new();
            entri.insert("id".to_string(), Value::String(id_str));
            let val_floats: Vec<Value> = vec_floats.into_iter().map(Value::Number).collect();
            entri.insert("vektor".to_string(), Value::Array(Rc::new(RefCell::new(val_floats))));
            entri.insert("metadata".to_string(), metadata_val);

            if let Some(Value::Array(items_arr)) = map.get("vektor") {
                items_arr.borrow_mut().push(Value::Map(Rc::new(RefCell::new(entri))));
            }

            Ok(Value::Bool(true))
        }
        _ => Err(Galat::runtime("Fungsi 'vektor_sisip' memerlukan objek BasisDataVektor", span)),
    }
}

fn cosine_similarity(v1: &[f64], v2: &[f64]) -> f64 {
    let mut dot = 0.0;
    let mut norm1 = 0.0;
    let mut norm2 = 0.0;
    for (a, b) in v1.iter().zip(v2.iter()) {
        dot += a * b;
        norm1 += a * a;
        norm2 += b * b;
    }
    if norm1 == 0.0 || norm2 == 0.0 {
        0.0
    } else {
        dot / (norm1.sqrt() * norm2.sqrt())
    }
}

fn builtin_vectordb_kueri_knn(args: &[Value], span: &Span) -> Result<Value, Galat> {
    if args.len() < 2 {
        return Err(Galat::runtime("Fungsi 'vektor_kueri_knn' menerima minimal (BasisDataVektor, vektor_kueri, [k])", span));
    }
    let db_val = &args[0];
    let query_vec_val = &args[1];
    let k = args.get(2).and_then(|v| match v {
        Value::Number(n) => Some(*n as usize),
        _ => None,
    }).unwrap_or(5);

    match db_val {
        Value::Map(m) => {
            let map = m.borrow();
            let dim = match map.get("dimensi") {
                Some(Value::Number(n)) => *n as usize,
                _ => 0,
            };

            let q_floats: Vec<f64> = match query_vec_val {
                Value::Array(arr) => {
                    let items = arr.borrow();
                    if items.len() != dim {
                        return Err(Galat::runtime(format!("Ukuran vektor kueri ({}) tidak cocok dengan dimensi database ({})", items.len(), dim), span));
                    }
                    items.iter().map(|v| match v {
                        Value::Number(n) => *n,
                        _ => 0.0,
                    }).collect()
                }
                _ => return Err(Galat::runtime("Vektor kueri harus berupa array angka", span)),
            };

            let mut scores: Vec<(f64, Value)> = Vec::new();
            if let Some(Value::Array(items_arr)) = map.get("vektor") {
                for item_val in items_arr.borrow().iter() {
                    if let Value::Map(im) = item_val {
                        let item_map = im.borrow();
                        if let Some(Value::Array(v_arr)) = item_map.get("vektor") {
                            let floats: Vec<f64> = v_arr.borrow().iter().map(|v| match v {
                                Value::Number(n) => *n,
                                _ => 0.0,
                            }).collect();
                            let sim = cosine_similarity(&q_floats, &floats);
                            let mut res_item = item_map.clone();
                            res_item.insert("kemiripan".to_string(), Value::Number(sim));
                            scores.push((sim, Value::Map(Rc::new(RefCell::new(res_item)))));
                        }
                    }
                }
            }

            scores.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal));
            let top_k: Vec<Value> = scores.into_iter().take(k).map(|(_, v)| v).collect();
            Ok(Value::Array(Rc::new(RefCell::new(top_k))))
        }
        _ => Err(Galat::runtime("Fungsi 'vektor_kueri_knn' memerlukan objek BasisDataVektor", span)),
    }
}

