// =========================================================================
// WIDYA_SHAMIR_SECRET (SHAMIR'S (k, n) THRESHOLD SCHEME OVER GF(256))
// =========================================================================

// Galois Field GF(2^8) arithmetic with irreducible polynomial x^8 + x^4 + x^3 + x + 1 (0x11B / 0x1B)
fn gf256_add(a: u8, b: u8) -> u8 {
    a ^ b
}

fn gf256_mul(mut a: u8, mut b: u8) -> u8 {
    let mut p: u8 = 0;
    for _ in 0..8 {
        if (b & 1) != 0 {
            p ^= a;
        }
        let high_bit_set = (a & 0x80) != 0;
        a <<= 1;
        if high_bit_set {
            a ^= 0x1b; // polynomial x^8 + x^4 + x^3 + x + 1
        }
        b >>= 1;
    }
    p
}

fn gf256_inv(a: u8) -> u8 {
    if a == 0 {
        return 0;
    }
    // Fermat's Little Theorem in GF(2^8): a^(-1) = a^(254)
    let mut res = 1u8;
    let mut base = a;
    let mut exp = 254;
    while exp > 0 {
        if exp % 2 == 1 {
            res = gf256_mul(res, base);
        }
        base = gf256_mul(base, base);
        exp /= 2;
    }
    res
}

fn gf256_div(a: u8, b: u8) -> u8 {
    if b == 0 {
        return 0;
    }
    gf256_mul(a, gf256_inv(b))
}

fn gf256_eval_poly(coeffs: &[u8], x: u8) -> u8 {
    let mut res = 0u8;
    for &coeff in coeffs.iter().rev() {
        res = gf256_add(gf256_mul(res, x), coeff);
    }
    res
}

fn builtin_shamir_bagi_rahasia(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let secret_bytes = match &args[0] {
        Value::String(s) => s.as_bytes().to_vec(),
        Value::Array(arr) => {
            let items = arr.borrow();
            items.iter().filter_map(|v| match v {
                Value::Number(n) => Some(*n as u8),
                _ => None,
            }).collect()
        }
        _ => return Err(Galat::runtime("Rahasia harus berupa string teks atau daftar byte", span)),
    };

    let k = match &args[1] {
        Value::Number(n) => {
            let val = *n as usize;
            if val < 2 {
                return Err(Galat::runtime("Ambang batas k (threshold) minimal 2", span));
            }
            val
        }
        _ => return Err(Galat::runtime("Ambang batas k harus berupa angka", span)),
    };

    let n = match &args[2] {
        Value::Number(num) => {
            let val = *num as usize;
            if val < k || val > 255 {
                return Err(Galat::runtime("Jumlah bagian n harus >= k dan <= 255", span));
            }
            val
        }
        _ => return Err(Galat::runtime("Jumlah bagian n harus berupa angka", span)),
    };

    let mut rng = rand::thread_rng();
    let mut share_data: Vec<(u8, Vec<u8>)> = (1..=n).map(|x| (x as u8, Vec::with_capacity(secret_bytes.len()))).collect();

    for &byte in &secret_bytes {
        let mut poly = Vec::with_capacity(k);
        poly.push(byte); // a_0 = secret byte
        for _ in 1..k {
            poly.push(rng.gen_range(0..=255u8));
        }

        for (x, y_list) in share_data.iter_mut() {
            let y = gf256_eval_poly(&poly, *x);
            y_list.push(y);
        }
    }

    let shares: Vec<Value> = share_data.into_iter().map(|(x, y_bytes)| {
        let hex_val: String = y_bytes.iter().map(|b| format!("{:02x}", b)).collect();
        let mut m = HashMap::new();
        m.insert("x".to_string(), Value::Number(x as f64));
        m.insert("data_hex".to_string(), Value::String(hex_val));
        Value::Map(Rc::new(RefCell::new(m)))
    }).collect();

    Ok(Value::Array(Rc::new(RefCell::new(shares))))
}

fn builtin_shamir_gabung_rahasia(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let shares_val = match &args[0] {
        Value::Array(arr) => arr.clone(),
        _ => return Err(Galat::runtime("Fungsi 'shamir_gabung_rahasia' memerlukan daftar bagian (shares)", span)),
    };

    let shares_borrowed = shares_val.borrow();
    if shares_borrowed.is_empty() {
        return Err(Galat::runtime("Daftar share tidak boleh kosong", span));
    }

    let mut parsed_shares: Vec<(u8, Vec<u8>)> = Vec::new();
    for share_item in shares_borrowed.iter() {
        match share_item {
            Value::Map(dict) => {
                let map = dict.borrow();
                let x = match map.get("x") {
                    Some(Value::Number(n)) => *n as u8,
                    _ => return Err(Galat::runtime("Share memerlukan koordinat x", span)),
                };
                let hex_str = match map.get("data_hex") {
                    Some(Value::String(s)) => s.clone(),
                    _ => return Err(Galat::runtime("Share memerlukan data_hex", span)),
                };

                let mut bytes = Vec::new();
                for i in (0..hex_str.len()).step_by(2) {
                    if i + 2 <= hex_str.len() {
                        if let Ok(b) = u8::from_str_radix(&hex_str[i..i + 2], 16) {
                            bytes.push(b);
                        }
                    }
                }
                parsed_shares.push((x, bytes));
            }
            _ => return Err(Galat::runtime("Elemen share harus berupa kamus objek share", span)),
        }
    }

    let byte_len = parsed_shares[0].1.len();
    for (_x, bytes) in &parsed_shares {
        if bytes.len() != byte_len {
            return Err(Galat::runtime("Panjang byte antar share tidak konsisten", span));
        }
    }

    let mut recovered = Vec::with_capacity(byte_len);

    for byte_idx in 0..byte_len {
        let mut secret_byte = 0u8;
        for i in 0..parsed_shares.len() {
            let (xi, yi_bytes) = &parsed_shares[i];
            let yi = yi_bytes[byte_idx];

            let mut li = 1u8;
            for j in 0..parsed_shares.len() {
                if i != j {
                    let (xj, _) = &parsed_shares[j];
                    let num = *xj; // (0 - xj) in GF(256) is xj
                    let den = gf256_add(*xi, *xj); // (xi - xj) in GF(256) is xi ^ xj
                    let term = gf256_div(num, den);
                    li = gf256_mul(li, term);
                }
            }

            secret_byte = gf256_add(secret_byte, gf256_mul(yi, li));
        }
        recovered.push(secret_byte);
    }

    if let Ok(s) = String::from_utf8(recovered.clone()) {
        Ok(Value::String(s))
    } else {
        let arr: Vec<Value> = recovered.into_iter().map(|b| Value::Number(b as f64)).collect();
        Ok(Value::Array(Rc::new(RefCell::new(arr))))
    }
}

// =========================================================================
// WIDYA_SNAPPY_LITE (FRAMED BYTE-ALIGNED STREAMING COMPRESSION CODEC)
// =========================================================================

fn snappy_compress_bytes(input: &[u8]) -> Vec<u8> {
    if input.is_empty() {
        return vec![0x00]; // Length 0 varint
    }

    let mut out = Vec::with_capacity(input.len() + 16);

    // Write uncompressed length as varint (up to 32-bit)
    let mut len = input.len();
    while len >= 0x80 {
        out.push(((len & 0x7f) as u8) | 0x80);
        len >>= 7;
    }
    out.push((len & 0x7f) as u8);

    let mut pos = 0;
    let mut table: HashMap<[u8; 4], usize> = HashMap::with_capacity(4096);
    let mut lit_start = 0;

    while pos + 4 <= input.len() {
        let chunk: [u8; 4] = [input[pos], input[pos + 1], input[pos + 2], input[pos + 3]];
        if let Some(&prev_pos) = table.get(&chunk) {
            let offset = pos - prev_pos;
            if offset > 0 && offset < 65536 {
                // Emit literals before this match
                if pos > lit_start {
                    emit_snappy_literal(&input[lit_start..pos], &mut out);
                }

                // Determine match length
                let mut match_len = 4;
                while pos + match_len < input.len() && input[prev_pos + match_len] == input[pos + match_len] && match_len < 64 {
                    match_len += 1;
                }

                // Emit copy tag
                emit_snappy_copy(offset, match_len, &mut out);

                pos += match_len;
                lit_start = pos;
                continue;
            }
        }

        table.insert(chunk, pos);
        pos += 1;
    }

    // Emit remaining literals
    if lit_start < input.len() {
        emit_snappy_literal(&input[lit_start..], &mut out);
    }

    out
}

fn emit_snappy_literal(lit: &[u8], out: &mut Vec<u8>) {
    let len = lit.len();
    if len == 0 {
        return;
    }
    if len <= 60 {
        let tag = ((len - 1) as u8) << 2; // tag type 00
        out.push(tag);
    } else {
        // Tag with extra length bytes
        out.push(0x3c << 2);
        out.push((len - 1) as u8);
    }
    out.extend_from_slice(lit);
}

fn emit_snappy_copy(offset: usize, len: usize, out: &mut Vec<u8>) {
    // 2-byte offset copy (tag type 02)
    let tag = (0x02) | (((len - 1) as u8) << 2);
    out.push(tag);
    out.push((offset & 0xff) as u8);
    out.push(((offset >> 8) & 0xff) as u8);
}

fn snappy_decompress_bytes(input: &[u8]) -> Result<Vec<u8>, String> {
    if input.is_empty() {
        return Ok(Vec::new());
    }

    // Read varint length
    let mut pos = 0;
    let mut uncompressed_len = 0usize;
    let mut shift = 0;
    while pos < input.len() {
        let b = input[pos];
        pos += 1;
        uncompressed_len |= ((b & 0x7f) as usize) << shift;
        if (b & 0x80) == 0 {
            break;
        }
        shift += 7;
    }

    if uncompressed_len == 0 {
        return Ok(Vec::new());
    }

    let mut out = Vec::with_capacity(uncompressed_len);

    while pos < input.len() {
        let tag = input[pos];
        pos += 1;
        let tag_type = tag & 0x03;

        match tag_type {
            0x00 => {
                // Literal
                let len = if (tag >> 2) < 60 {
                    ((tag >> 2) as usize) + 1
                } else {
                    if pos >= input.len() { return Err("Corrupted snappy stream".to_string()); }
                    let extra = input[pos] as usize;
                    pos += 1;
                    extra + 1
                };

                if pos + len > input.len() {
                    return Err("Snappy literal length exceeds stream".to_string());
                }
                out.extend_from_slice(&input[pos..pos + len]);
                pos += len;
            }
            0x02 => {
                // Copy with 2-byte offset
                let len = ((tag >> 2) as usize) + 1;
                if pos + 2 > input.len() {
                    return Err("Snappy truncated copy offset".to_string());
                }
                let offset = (input[pos] as usize) | ((input[pos + 1] as usize) << 8);
                pos += 2;

                if offset == 0 || offset > out.len() {
                    return Err(format!("Invalid copy offset {} in snappy buffer of size {}", offset, out.len()));
                }

                let start = out.len() - offset;
                for i in 0..len {
                    let b = out[start + i];
                    out.push(b);
                }
            }
            _ => {
                // Fallback literal
                let len = ((tag >> 2) as usize) + 1;
                if pos + len <= input.len() {
                    out.extend_from_slice(&input[pos..pos + len]);
                    pos += len;
                }
            }
        }
    }

    Ok(out)
}

fn builtin_snappy_kompres(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let input_bytes = match &args[0] {
        Value::String(s) => s.as_bytes().to_vec(),
        Value::Array(arr) => {
            let items = arr.borrow();
            items.iter().filter_map(|v| match v {
                Value::Number(n) => Some(*n as u8),
                _ => None,
            }).collect()
        }
        _ => return Err(Galat::runtime("Argumen 'snappy_kompres' harus berupa string teks atau array byte", span)),
    };

    let comp = snappy_compress_bytes(&input_bytes);
    let hex: String = comp.iter().map(|b| format!("{:02x}", b)).collect();
    Ok(Value::String(hex))
}

fn builtin_snappy_dekompres(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let raw_bytes = match &args[0] {
        Value::String(s) => {
            let mut bytes = Vec::new();
            for i in (0..s.len()).step_by(2) {
                if i + 2 <= s.len() {
                    if let Ok(b) = u8::from_str_radix(&s[i..i + 2], 16) {
                        bytes.push(b);
                    }
                }
            }
            bytes
        }
        Value::Array(arr) => {
            let items = arr.borrow();
            items.iter().filter_map(|v| match v {
                Value::Number(n) => Some(*n as u8),
                _ => None,
            }).collect()
        }
        _ => return Err(Galat::runtime("Argumen 'snappy_dekompres' harus berupa string hex atau array byte", span)),
    };

    match snappy_decompress_bytes(&raw_bytes) {
        Ok(decomp) => {
            if let Ok(s) = String::from_utf8(decomp.clone()) {
                Ok(Value::String(s))
            } else {
                let arr: Vec<Value> = decomp.into_iter().map(|b| Value::Number(b as f64)).collect();
                Ok(Value::Array(Rc::new(RefCell::new(arr))))
            }
        }
        Err(e) => Err(Galat::runtime(format!("Gagal dekompresi snappy: {}", e), span)),
    }
}

fn builtin_snappy_rasio_hemat(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let input_bytes = match &args[0] {
        Value::String(s) => s.as_bytes().to_vec(),
        Value::Array(arr) => {
            let items = arr.borrow();
            items.iter().filter_map(|v| match v {
                Value::Number(n) => Some(*n as u8),
                _ => None,
            }).collect()
        }
        _ => return Err(Galat::runtime("Argumen 'snappy_rasio_hemat' harus berupa string teks atau array byte", span)),
    };

    let orig_len = input_bytes.len();
    if orig_len == 0 {
        return Ok(Value::Number(0.0));
    }

    let comp = snappy_compress_bytes(&input_bytes);
    let ratio = 1.0 - (comp.len() as f64 / orig_len as f64);
    Ok(Value::Number(ratio.max(0.0)))
}

// =========================================================================
// WIDYA_KADEMLIA (K-BUCKET ROUTING & XOR METRIC P2P DHT)
// =========================================================================

fn kademlia_hash_id(s: &str) -> [u8; 20] {
    let mut hasher = Sha256::new();
    hasher.update(s.as_bytes());
    let res = hasher.finalize();
    let mut out = [0u8; 20];
    out.copy_from_slice(&res[..20]);
    out
}

fn kademlia_xor_distance(a: &[u8; 20], b: &[u8; 20]) -> [u8; 20] {
    let mut dist = [0u8; 20];
    for i in 0..20 {
        dist[i] = a[i] ^ b[i];
    }
    dist
}

fn builtin_kademlia_buat(args: &[Value], _span: &Span) -> Result<Value, Galat> {
    let local_id_str = if !args.is_empty() {
        args[0].to_string_repr()
    } else {
        "node-local-01".to_string()
    };

    let k_bucket_size = if args.len() > 1 {
        match &args[1] {
            Value::Number(n) => (*n as usize).max(1),
            _ => 20,
        }
    } else {
        20
    };

    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("WidyaKademlia".to_string()));
    map.insert("local_id".to_string(), Value::String(local_id_str));
    map.insert("k".to_string(), Value::Number(k_bucket_size as f64));
    map.insert("nodes".to_string(), Value::Array(Rc::new(RefCell::new(Vec::new()))));
    map.insert("storage".to_string(), Value::Map(Rc::new(RefCell::new(HashMap::new()))));

    Ok(Value::Map(Rc::new(RefCell::new(map))))
}

fn builtin_kademlia_tambah_node(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let node_id_str = args[1].to_string_repr();
    match &args[0] {
        Value::Map(m) => {
            let map = m.borrow();
            if let Some(Value::Array(nodes_arr)) = map.get("nodes") {
                let mut nodes = nodes_arr.borrow_mut();
                // Check if already exists
                let mut found = false;
                for item in nodes.iter_mut() {
                    if let Value::Map(im) = item {
                        let im_map = im.borrow();
                        if let Some(Value::String(id)) = im_map.get("id") {
                            if id == &node_id_str {
                                found = true;
                                break;
                            }
                        }
                    }
                }
                if !found {
                    let mut node_obj = HashMap::new();
                    node_obj.insert("id".to_string(), Value::String(node_id_str.clone()));
                    node_obj.insert("address".to_string(), args.get(2).cloned().unwrap_or(Value::String("127.0.0.1".to_string())));
                    nodes.push(Value::Map(Rc::new(RefCell::new(node_obj))));
                }
                return Ok(Value::Bool(true));
            }
            Err(Galat::runtime("Objek Kademlia tidak valid", span))
        }
        _ => Err(Galat::runtime("Fungsi 'kademlia_tambah_node' memerlukan instance TabelKademlia", span)),
    }
}

fn builtin_kademlia_node_terdekat(args: &[Value], span: &Span) -> Result<Value, Galat> {
    let target_key = args[1].to_string_repr();
    let count = if args.len() > 2 {
        match &args[2] { Value::Number(n) => *n as usize, _ => 5 }
    } else {
        5
    };

    let target_hash = kademlia_hash_id(&target_key);

    match &args[0] {
        Value::Map(m) => {
            let map = m.borrow();
            if let Some(Value::Array(nodes_arr)) = map.get("nodes") {
                let nodes = nodes_arr.borrow();
                let mut scored: Vec<([u8; 20], Value)> = Vec::new();

                for item in nodes.iter() {
                    if let Value::Map(im) = item {
                        let im_map = im.borrow();
                        if let Some(Value::String(id)) = im_map.get("id") {
                            let nh = kademlia_hash_id(id);
                            let dist = kademlia_xor_distance(&nh, &target_hash);
                            scored.push((dist, item.clone()));
                        }
                    }
                }

                scored.sort_by(|a, b| a.0.cmp(&b.0));
                let res: Vec<Value> = scored.into_iter().take(count).map(|(_, v)| v).collect();
                return Ok(Value::Array(Rc::new(RefCell::new(res))));
            }
            Err(Galat::runtime("Objek Kademlia tidak valid", span))
        }
        _ => Err(Galat::runtime("Fungsi 'kademlia_node_terdekat' memerlukan instance TabelKademlia", span)),
    }
}

