    let mut map = HashMap::new();
    map.insert("_tipe".to_string(), Value::String("WidyaMerklePatriciaTrie".to_string()));
    map.insert("entries".to_string(), Value::Map(Rc::new(RefCell::new(HashMap::new()))));
